package oviewer

import (
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"

	"github.com/gdamore/tcell/v2"
	"github.com/mattn/go-runewidth"
)

// content represents one screen cell.
type content struct {
	mainc rune
	combc []rune
	width int
