var DefaultContent = content{mainc: ' ', width: 1, style: tcell.StyleDefault}

// placeholder cell for the right half of a wide character.
var wideRight = content{mainc: 0, width: 0, style: tcell.StyleDefault}

func init() {
	runewidth.DefaultCondition.EastAsianWidth = false
