// lineContents holds converted contents and position maps.
type lineContents struct {
	lc  contents
	str string // string made from contents (one rune or more per cell)
	pos []int  // byte offset in str -> cell index (len(str)+1 entries)
}

// convertMode
const (
	convES = iota
	convRaw
)

type parseState struct {
	style    tcell.Style
	plain    bool
	tabWidth int
	x        int // width counter for tab stops
	lc       contents
	bsFlag   bool
	url      string
	urlID    string
}

func runeWidth(r rune) int {
	return runewidth.RuneWidth(r)
}

// parseLine converts a raw line into contents.
func parseLine(line string, tabWidth int, conv int, plain bool) contents {
	st := &parseState{style: tcell.StyleDefault, plain: plain, tabWidth: tabWidth}
	st.lc = make(contents, 0, len(line))
	i := 0
	n := len(line)
	for i < n {
		b := line[i]
		if b == 0x1b {
			if conv == convRaw {
				st.appendRune('^', 1)
				st.appendRune('[', 1)
				i++
				continue
			}
			i = st.parseEscape(line, i)
			continue
		}
		r, size := utf8.DecodeRuneInString(line[i:])
		if r == utf8.RuneError && size <= 1 {
			// invalid byte
			st.appendRune('?', 1)
			i++
			continue
		}
		i += size
		switch r {
		case '\t':
			tw := st.tabWidth
			if tw <= 0 {
				st.appendRune('\t', 0)
				continue
			}
			sp := tw - (st.x % tw)
			for k := 0; k < sp; k++ {
				st.lc = append(st.lc, content{mainc: ' ', width: 1, style: st.style})
			}
			st.x += sp
			continue
		case '\b':
			st.bsFlag = true
			continue
		case '\r':
			continue
		case '\n':
			continue
		}
		if st.bsFlag {
			st.bsFlag = false
			if st.backspace(r) {
				continue
			}
		}
		if r < 0x20 || r == 0x7f {
			st.lc = append(st.lc, content{mainc: ' ', width: 0, style: st.style})
			continue
		}
		w := runeWidth(r)
		if w == 0 {
			if unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Me, r) || unicode.Is(unicode.Mc, r) || r == 0x200d || (r >= 0xfe00 && r <= 0xfe0f) {
				if len(st.lc) > 0 {
					last := len(st.lc) - 1
					if st.lc[last].width == 0 && last > 0 && st.lc[last].mainc == 0 {
						last--
					}
					st.lc[last].combc = append(st.lc[last].combc, r)
					continue
				}
			}
