				last := len(st.lc) - 1
				if st.lc[last].width == 0 && last > 0 && st.lc[last].mainc == 0 {
					last--
				}
				st.lc[last].combc = append(st.lc[last].combc, r)
				continue
			}
			st.lc = append(st.lc, content{mainc: r, width: 0, style: st.style})
			continue
		}
