}

func (st *parseState) curStyle() tcell.Style {
	return st.style
}

func (st *parseState) appendRune(r rune, w int) {
	s := st.style
	if w == 2 {
		st.lc = append(st.lc, content{mainc: r, width: 2, style: s})
		st.lc = append(st.lc, content{mainc: 0, width: 0, style: s})
		st.x += 2
		return
	}
	st.lc = append(st.lc, content{mainc: r, width: w, style: s})
	st.x += w
}

// backspace handles overstrike sequences. returns true if consumed.
func (st *parseState) backspace(r rune) bool {
	if len(st.lc) == 0 {
		return false
	}
	last := len(st.lc) - 1
	if st.lc[last].width == 0 && st.lc[last].mainc == 0 && last > 0 {
		last--
	}
	prev := st.lc[last]
	w := runeWidth(r)
	if prev.mainc == r {
		st.lc[last].style = applyStyle(st.style, styleOverStrike)
		return true
	}
	if prev.mainc == '_' {
		st.lc = st.lc[:last]
		st.x -= prev.width
		s := applyStyle(st.style, styleOverLine)
		if w == 2 {
			st.lc = append(st.lc, content{mainc: r, width: 2, style: s}, content{mainc: 0, width: 0, style: s})
		} else {
			st.lc = append(st.lc, content{mainc: r, width: w, style: s})
		}
		st.x += w
		return true
	}
	if r == '_' {
		st.lc[last].style = applyStyle(st.lc[last].style, styleOverLine)
		return true
	}
	// replace
	st.lc = st.lc[:last]
	st.x -= prev.width
	return false
}

// parseEscape parses an escape sequence starting at i (line[i] == ESC).
func (st *parseState) parseEscape(line string, i int) int {
	n := len(line)
	if i+1 >= n {
		return n
	}
	c := line[i+1]
	switch c {
	case '[':
		j := i + 2
		for j < n {
			b := line[j]
			if b >= 0x40 && b <= 0x7e {
				break
			}
			j++
		}
		if j >= n {
			return n
		}
		final := line[j]
		params := line[i+2 : j]
		if final == 'm' {
			if !st.plain {
				st.style = csiStyle(st.style, params)
			}
		}
		return j + 1
	case ']':
		// OSC
		j := i + 2
		end := -1
		next := n
		for j < n {
			if line[j] == 0x07 {
				end = j
				next = j + 1
				break
			}
			if line[j] == 0x1b && j+1 < n && line[j+1] == '\\' {
				end = j
				next = j + 2
				break
			}
			j++
		}
		if end < 0 {
			return n
		}
		st.osc(line[i+2 : end])
		return next
	case 'P', 'X', '^', '_':
		j := i + 2
		for j < n {
			if line[j] == 0x07 {
				return j + 1
			}
			if line[j] == 0x1b && j+1 < n && line[j+1] == '\\' {
				return j + 2
			}
			j++
		}
		return n
	case '(', ')', '*', '+', '#', '%':
		if i+2 < n {
			return i + 3
		}
		return n
	default:
		return i + 2
	}
}

func (st *parseState) osc(s string) {
	if strings.HasPrefix(s, "8;") {
		rest := s[2:]
		idx := strings.IndexByte(rest, ';')
		if idx < 0 {
			return
		}
		params := rest[:idx]
		url := rest[idx+1:]
		id := ""
		for _, p := range strings.Split(params, ":") {
			if strings.HasPrefix(p, "id=") {
				id = p[3:]
			}
		}
		if st.plain {
			return
		}
		st.style = st.style.Url(url)
		if id != "" {
			st.style = st.style.UrlId(id)
		} else {
			st.style = st.style.UrlId("")
		}
	}
}

// csiStyle applies SGR parameters to style.
func csiStyle(style tcell.Style, params string) tcell.Style {
	if params == "" {
		return tcell.StyleDefault.Url(styleURL(style))
	}
	fields := strings.Split(params, ";")
	for idx := 0; idx < len(fields); idx++ {
		f := fields[idx]
		sub := ""
		if k := strings.IndexByte(f, ':'); k >= 0 {
			sub = f[k+1:]
			f = f[:k]
		}
		if f == "" {
			f = "0"
		}
		num, err := strconv.Atoi(f)
		if err != nil {
			return style
		}
		switch {
		case num == 0:
			style = tcell.StyleDefault.Url(styleURL(style))
		case num == 1:
			style = style.Bold(true)
		case num == 2:
			style = style.Dim(true)
		case num == 3:
			style = style.Italic(true)
		case num == 4:
			if sub != "" {
				switch sub {
				case "0":
					style = style.Underline(false)
				case "1":
					style = style.Underline(true)
				case "2":
					style = style.Underline(tcell.UnderlineStyleDouble)
				case "3":
					style = style.Underline(tcell.UnderlineStyleCurly)
				case "4":
					style = style.Underline(tcell.UnderlineStyleDotted)
				case "5":
					style = style.Underline(tcell.UnderlineStyleDashed)
				default:
					style = style.Underline(true)
				}
			} else {
				style = style.Underline(true)
			}
		case num == 5 || num == 6:
			style = style.Blink(true)
		case num == 7:
			style = style.Reverse(true)
		case num == 8:
		case num == 9:
			style = style.StrikeThrough(true)
		case num == 21:
			style = style.Underline(tcell.UnderlineStyleDouble)
		case num == 22:
			style = style.Bold(false).Dim(false)
		case num == 23:
			style = style.Italic(false)
		case num == 24:
			style = style.Underline(false)
		case num == 25:
			style = style.Blink(false)
		case num == 27:
			style = style.Reverse(false)
		case num == 29:
			style = style.StrikeThrough(false)
		case num >= 30 && num <= 37:
			style = style.Foreground(tcell.PaletteColor(num - 30))
		case num == 38, num == 48, num == 58:
			var color tcell.Color
			var ok bool
			if sub != "" {
				color, ok = parseColorSub(sub)
			} else {
				var used int
				color, used, ok = parseColorFields(fields[idx+1:])
				idx += used
			}
			if !ok {
				continue
			}
			switch num {
			case 38:
				style = style.Foreground(color)
			case 48:
				style = style.Background(color)
			case 58:
				style = style.Underline(color)
			}
		case num == 39:
			style = style.Foreground(tcell.ColorDefault)
		case num >= 40 && num <= 47:
			style = style.Background(tcell.PaletteColor(num - 40))
		case num == 49:
			style = style.Background(tcell.ColorDefault)
		case num == 59:
			style = style.Underline(tcell.ColorDefault)
		case num >= 90 && num <= 97:
			style = style.Foreground(tcell.PaletteColor(num - 90 + 8))
		case num >= 100 && num <= 107:
			style = style.Background(tcell.PaletteColor(num - 100 + 8))
		}
	}
	return style
}

func styleURL(s tcell.Style) string {
	u, _ := s.GetUrl()
	return u
}

func parseColorFields(f []string) (tcell.Color, int, bool) {
	if len(f) == 0 {
		return tcell.ColorDefault, 0, false
	}
	switch f[0] {
	case "5":
		if len(f) < 2 {
			return tcell.ColorDefault, len(f), false
		}
		n, err := strconv.Atoi(f[1])
		if err != nil || n < 0 || n > 255 {
			return tcell.ColorDefault, 2, false
		}
		return tcell.PaletteColor(n), 2, true
	case "2":
		if len(f) < 4 {
			return tcell.ColorDefault, len(f), false
		}
		r, e1 := strconv.Atoi(f[1])
		g, e2 := strconv.Atoi(f[2])
		b, e3 := strconv.Atoi(f[3])
		if e1 != nil || e2 != nil || e3 != nil {
			return tcell.ColorDefault, 4, false
		}
		return tcell.NewRGBColor(int32(r), int32(g), int32(b)), 4, true
	}
	return tcell.ColorDefault, 1, false
}

func parseColorSub(sub string) (tcell.Color, bool) {
	f := strings.Split(sub, ":")
	if len(f) > 0 && f[0] == "2" && len(f) == 5 {
		// 38:2:cs:r:g:b form
		f = []string{"2", f[2], f[3], f[4]}
	}
	c, _, ok := parseColorFields(f)
	return c, ok
}

// contentsToString converts contents into a string and position map.
func contentsToString(lc contents) (string, []int) {
	var b strings.Builder
	pos := make([]int, 0, len(lc)+1)
	for i, c := range lc {
		if c.width == 0 && c.mainc == 0 {
			continue
		}
		start := b.Len()
		_ = start
		r := c.mainc
		b.WriteRune(r)
		for _, cr := range c.combc {
			b.WriteRune(cr)
		}
		for len(pos) < b.Len() {
			pos = append(pos, i)
		}
	}
	pos = append(pos, len(lc))
	return b.String(), pos
}
