// ToTcellStyle converts OVStyle to tcell.Style based on default.
func ToTcellStyle(s OVStyle) tcell.Style {
	return applyStyle(tcell.StyleDefault, s)
}

func getColor(name string) tcell.Color {
	if name == "default" {
		return tcell.ColorDefault
	}
	return tcell.GetColor(name)
}

func applyStyle(style tcell.Style, s OVStyle) tcell.Style {
	if s.Foreground != "" {
		style = style.Foreground(getColor(s.Foreground))
	}
	if s.Background != "" {
		style = style.Background(getColor(s.Background))
	}
	if s.Blink {
		style = style.Blink(true)
	}
	if s.Bold {
		style = style.Bold(true)
	}
	if s.Dim {
		style = style.Dim(true)
	}
	if s.Italic {
		style = style.Italic(true)
	}
	if s.Reverse {
		style = style.Reverse(true)
	}
	if s.StrikeThrough {
		style = style.StrikeThrough(true)
	}
	if s.Underline {
		style = style.Underline(true)
	}
	if s.UnderlineStyle != "" {
		switch strings.ToLower(s.UnderlineStyle) {
		case "0", "none":
			style = style.Underline(false)
		case "1", "solid", "single":
			style = style.Underline(tcell.UnderlineStyleSolid)
		case "2", "double":
			style = style.Underline(tcell.UnderlineStyleDouble)
		case "3", "curly":
			style = style.Underline(tcell.UnderlineStyleCurly)
		case "4", "dotted":
			style = style.Underline(tcell.UnderlineStyleDotted)
		case "5", "dashed":
			style = style.Underline(tcell.UnderlineStyleDashed)
		}
	}
	if s.UnderlineColor != "" {
		style = style.Underline(getColor(s.UnderlineColor))
	}
	if s.UnBlink {
		style = style.Blink(false)
	}
	if s.UnBold {
		style = style.Bold(false)
	}
	if s.UnDim {
		style = style.Dim(false)
	}
	if s.UnItalic {
		style = style.Italic(false)
	}
	if s.UnReverse {
		style = style.Reverse(false)
	}
	if s.UnStrikeThrough {
		style = style.StrikeThrough(false)
	}
	if s.UnUnderline {
		style = style.Underline(false)
	}
	return style
}

