	}
	var raw map[string]interface{}
	if err := yaml.Unmarshal(data, &raw); err != nil {
		return fmt.Errorf("While parsing config: %w", err)
	}
	m, _ := lowerKeys(raw).(map[string]interface{})
	applyConfigMap(config, m)
	return nil
}

func applyConfigMap(c *Config, m map[string]interface{}) {
	// legacy top-level styles
	legacy := map[string]string{
		"stylealternate":            "alternate",
		"styleheader":               "header",
		"stylebody":                 "body",
		"styleoverstrike":           "overstrike",
		"styleoverline":             "overline",
		"stylelinenumber":           "linenumber",
		"stylesearchhighlight":      "searchhighlight",
		"stylecolumnhighlight":      "columnhighlight",
		"stylemarkline":             "markline",
		"stylesectionline":          "sectionline",
		"styleverticalheader":       "verticalheader",
		"stylejumptargetline":       "jumptargetline",
		"styleverticalheaderborder": "verticalheaderborder",
		"stylemulticolorhighlight":  "multicolorhighlight",
		"stylecolumnrainbow":        "columnrainbow",
		"styleruler":                "ruler",
		"styleheaderborder":         "headerborder",
		"stylesectionheaderborder":  "sectionheaderborder",
	}
	lm := map[string]interface{}{}
	for k, v := range m {
		if name, ok := legacy[k]; ok {
			lm[name] = v
		}
	}
	if len(lm) > 0 {
		applyStylesMap(&c.General.Style, lm)
	}
	for k, v := range m {
		switch k {
		case "general":
			if gm, ok := v.(map[string]interface{}); ok {
				applyGeneralMap(&c.General, gm)
			}
		case "mode":
			if mm, ok := v.(map[string]interface{}); ok {
				for name, mv := range mm {
					if gm, ok := mv.(map[string]interface{}); ok {
						c.Mode[name] = gm
					} else {
						c.Mode[name] = map[string]interface{}{}
					}
				}
			}
		case "keybind":
			if km, ok := v.(map[string]interface{}); ok {
				for name, kv := range km {
					c.KeyBind[name] = toStringSlice(kv)
				}
			}
		case "defaultkeybind":
			c.DefaultKeyBind, _ = toString(v)
		case "casesensitive":
			c.CaseSensitive, _ = toBool(v)
		case "smartcasesensitive":
			c.SmartCaseSensitive, _ = toBool(v)
		case "regexpsearch":
			c.RegexpSearch, _ = toBool(v)
		case "incsearch":
			c.Incsearch, _ = toBool(v)
		case "memorylimit":
			c.MemoryLimit, _ = toInt(v)
		case "memorylimitfile":
			c.MemoryLimitFile, _ = toInt(v)
		case "disablemouse":
			c.DisableMouse, _ = toBool(v)
		case "disablecolumncycle":
			c.DisableColumnCycle, _ = toBool(v)
		case "disablestickyfollow":
			c.DisableStickyFollow, _ = toBool(v)
		case "quitsmall":
			c.QuitSmall, _ = toBool(v)
		case "quitsmallfilter":
			c.QuitSmallFilter, _ = toBool(v)
		case "iswriteoriginal":
			c.IsWriteOriginal, _ = toBool(v)
		case "beforewriteoriginal":
			c.BeforeWriteOriginal, _ = toInt(v)
		case "afterwriteoriginal":
			c.AfterWriteOriginal, _ = toInt(v)
		case "viewmode":
			c.ViewMode, _ = toString(v)
		case "shrinkchar":
			c.ShrinkChar, _ = toString(v)
		case "readwaittime":
			if s, ok := toString(v); ok {
				if d, err := time.ParseDuration(s); err == nil {
					c.ReadWaitTime = d
				} else if n, err := strconv.Atoi(s); err == nil {
					c.ReadWaitTime = time.Duration(n)
				}
			}
		case "clipboardmethod":
			c.ClipboardMethod, _ = toString(v)
		case "setterminaltitle":
			c.SetTerminalTitle, _ = toBool(v)
		case "debug":
			c.Debug, _ = toBool(v)
		case "notifyeof":
			c.NotifyEOF, _ = toInt(v)
		}
	}
}
EOF
echo ok

