}

func keysString(keys []string) string {
	var b strings.Builder
	for i, k := range keys {
		if i > 0 {
			b.WriteString(", ")
		}
		b.WriteString("[" + k + "]")
	}
	return b.String()
}

// KeyBindString returns the help string of key bindings.
