}

// ---- key decoding ----

type keyCode struct {
	mod tcell.ModMask
	key tcell.Key
	ch  rune
}

var keyNames = map[string]tcell.Key{
	"enter":     tcell.KeyEnter,
	"backspace": tcell.KeyBackspace2,
	"tab":       tcell.KeyTab,
	"backtab":   tcell.KeyBacktab,
	"esc":       tcell.KeyEscape,
	"escape":    tcell.KeyEscape,
	"delete":    tcell.KeyDelete,
	"del":       tcell.KeyDelete,
	"insert":    tcell.KeyInsert,
	"ins":       tcell.KeyInsert,
	"up":        tcell.KeyUp,
	"down":      tcell.KeyDown,
	"left":      tcell.KeyLeft,
	"right":     tcell.KeyRight,
	"home":      tcell.KeyHome,
	"end":       tcell.KeyEnd,
	"pageup":    tcell.KeyPgUp,
	"pgup":      tcell.KeyPgUp,
	"pagedown":  tcell.KeyPgDn,
	"pgdn":      tcell.KeyPgDn,
}

func decodeKey(s string) (keyCode, bool) {
	var kc keyCode
	look := s
	for {
		l := strings.ToLower(look)
		switch {
		case strings.HasPrefix(l, "ctrl+") && len(look) > 5:
			kc.mod |= tcell.ModCtrl
			look = look[5:]
			continue
		case strings.HasPrefix(l, "alt+") && len(look) > 4:
			kc.mod |= tcell.ModAlt
			look = look[4:]
			continue
		case strings.HasPrefix(l, "meta+") && len(look) > 5:
			kc.mod |= tcell.ModMeta
			look = look[5:]
			continue
		case strings.HasPrefix(l, "shift+") && len(look) > 6:
			kc.mod |= tcell.ModShift
			look = look[6:]
			continue
		}
		break
	}
	l := strings.ToLower(look)
	if k, ok := keyNames[l]; ok {
		kc.key = k
		return kc, true
	}
	if l == "space" {
		kc.key = tcell.KeyRune
		kc.ch = ' '
		return kc, true
	}
	if len(l) >= 2 && l[0] == 'f' {
		n := 0
		okn := true
		for _, c := range l[1:] {
			if c < '0' || c > '9' {
				okn = false
				break
			}
			n = n*10 + int(c-'0')
		}
		if okn && n >= 1 && n <= 64 {
			kc.key = tcell.KeyF1 + tcell.Key(n-1)
			return kc, true
		}
	}
	rs := []rune(look)
	if len(rs) != 1 {
		return kc, false
	}
	ch := rs[0]
	if kc.mod&tcell.ModCtrl != 0 {
		lc := unicode.ToLower(ch)
		if lc >= 'a' && lc <= 'z' {
			kc.key = tcell.KeyCtrlA + tcell.Key(lc-'a')
			return kc, true
		}
		switch ch {
		case ' ', '@', '2':
			kc.key = tcell.KeyCtrlSpace
			return kc, true
		case '\\':
			kc.key = tcell.KeyCtrlBackslash
			return kc, true
		case ']':
			kc.key = tcell.KeyCtrlRightSq
			return kc, true
		case '^', '6':
			kc.key = tcell.KeyCtrlCarat
			return kc, true
		case '_', '-':
			kc.key = tcell.KeyCtrlUnderscore
			return kc, true
		}
	}
	kc.key = tcell.KeyRune
	kc.ch = ch
	return kc, true
}

// eventMatches tests whether the event matches the key code.
func eventMatches(ev *tcell.EventKey, kc keyCode) bool {
	evMod := ev.Modifiers()
	evKey := ev.Key()
	if kc.key == tcell.KeyRune {
		if evKey != tcell.KeyRune {
			// ctrl+space etc
			return false
		}
		if ev.Rune() != kc.ch {
			return false
		}
		m := evMod &^ tcell.ModShift
		km := kc.mod &^ tcell.ModShift
		if kc.mod&tcell.ModShift != 0 && evMod&tcell.ModShift == 0 {
			// shift+x matches X
			if unicode.ToUpper(kc.ch) != ev.Rune() && kc.ch != ev.Rune() {
				return false
			}
		}
		return normMod(m) == normMod(km)
	}
	// ctrl keys
	if kc.key >= tcell.KeyCtrlA && kc.key <= tcell.KeyCtrlZ || kc.key == tcell.KeyCtrlSpace ||
		kc.key == tcell.KeyCtrlBackslash || kc.key == tcell.KeyCtrlRightSq || kc.key == tcell.KeyCtrlCarat || kc.key == tcell.KeyCtrlUnderscore {
		if evKey != kc.key {
			// tcell may report ctrl+letter as rune with ModCtrl
			if evKey == tcell.KeyRune && evMod&tcell.ModCtrl != 0 {
				lc := unicode.ToLower(ev.Rune())
				if lc >= 'a' && lc <= 'z' && tcell.KeyCtrlA+tcell.Key(lc-'a') == kc.key {
					return normMod(evMod&^tcell.ModShift) == normMod(kc.mod)
				}
			}
			return false
		}
		em := evMod | tcell.ModCtrl
		return normMod(em&^tcell.ModShift) == normMod((kc.mod|tcell.ModCtrl)&^tcell.ModShift)
	}
	if evKey != kc.key {
		// Enter/Tab/Backspace aliases
		if !keyAlias(evKey, kc.key) {
			return false
		}
	}
	km := kc.mod
	em := evMod
	switch kc.key {
	case tcell.KeyEnter, tcell.KeyTab, tcell.KeyBackspace2, tcell.KeyBackspace, tcell.KeyEscape, tcell.KeyBacktab:
		em &^= tcell.ModCtrl
		km &^= tcell.ModCtrl
	}
	return normMod(em) == normMod(km)
}

func keyAlias(a, b tcell.Key) bool {
	if (a == tcell.KeyBackspace || a == tcell.KeyBackspace2) && (b == tcell.KeyBackspace || b == tcell.KeyBackspace2) {
		return true
	}
	return false
}

func normMod(m tcell.ModMask) tcell.ModMask {
	if m&tcell.ModMeta != 0 {
		m = (m &^ tcell.ModMeta) | tcell.ModAlt
	}
	return m
}

// keyMatcher binds events to actions.
type keyMatcher struct {
	entries []keyEntry
}

type keyEntry struct {
	kc     keyCode
	action string
}

func newKeyMatcher(kb KeyBind, names []string) *keyMatcher {
	km := &keyMatcher{}
	for _, name := range names {
		for _, k := range kb[name] {
			kc, ok := decodeKey(k)
			if !ok {
				continue
			}
			km.entries = append(km.entries, keyEntry{kc: kc, action: name})
		}
	}
	return km
}

func (km *keyMatcher) match(ev *tcell.EventKey) string {
	for _, e := range km.entries {
		if eventMatches(ev, e.kc) {
			return e.action
		}
	}
	return ""
}

func allActionNames() []string {
	var names []string
	for _, g := range actionGroups {
		for _, a := range g.actions {
			names = append(names, a.name)
		}
	}
	return names
}

func normalActionNames() []string {
	var names []string
	for _, g := range actionGroups {
		if g.title == "Key binding when typing" {
			continue
		}
		for _, a := range g.actions {
			names = append(names, a.name)
		}
	}
	return names
}

func inputActionNames() []string {
	for _, g := range actionGroups {
		if g.title == "Key binding when typing" {
			var names []string
			for _, a := range g.actions {
				names = append(names, a.name)
			}
			return names
		}
	}
	return nil
}
EOF
echo ok"}

