	})
	cmd.SetUsageFunc(func(c *cobra.Command) error {
		fmt.Fprint(c.OutOrStderr(), helpText(c))
		return nil
	})
	return cmd
}

func helpText(c *cobra.Command) string {
	var b strings.Builder
	b.WriteString(c.Long)
	b.WriteString("\n")
	b.WriteString("Usage:\n")
	b.WriteString("  " + c.Use + "\n\n")
	b.WriteString("Flags:\n")
	fmt.Fprintf(&b, "%-48s%s\n", "Short   Long", "Purpose")
	c.Flags().VisitAll(func(fl *pflag.Flag) {
		if fl.Hidden {
			return
		}
		var line string
		if fl.Shorthand != "" {
			line = fmt.Sprintf("  -%s, --%s", fl.Shorthand, fl.Name)
		} else {
			line = fmt.Sprintf("      --%s", fl.Name)
		}
		varname, usage := pflag.UnquoteUsage(fl)
		if varname != "" {
			line += " " + varname
		}
		if fl.Value.Type() == "bool" && fl.DefValue == "true" {
			line += "[=true|false]"
		}
		if len(line) < 48 {
			line += strings.Repeat(" ", 48-len(line))
		} else {
			line += " "
		}
		line += usage
		if !isZeroDefault(fl) {
			if fl.Value.Type() == "string" {
				line += fmt.Sprintf(" (default %q)", fl.DefValue)
			} else {
				line += fmt.Sprintf(" (default %s)", fl.DefValue)
			}
		}
		b.WriteString(line + "\n")
	})
	return b.String()
}

func isZeroDefault(fl *pflag.Flag) bool {
	switch fl.Value.Type() {
	case "bool":
		return fl.DefValue == "false"
	case "int":
		return fl.DefValue == "0"
	case "string":
		return fl.DefValue == ""
	case "stringSlice":
		return fl.DefValue == "[]" || fl.DefValue == ""
	}
	return fl.DefValue == "" || fl.DefValue == "0"
}

func configPaths() []string {
	var paths []string
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
		paths = append(paths, filepath.Join(xdg, "ov", "config.yaml"), filepath.Join(xdg, "ov", "config.yml"))
	}
	if home, err := os.UserHomeDir(); err == nil {
		paths = append(paths, filepath.Join(home, ".config", "ov", "config.yaml"), filepath.Join(home, ".config", "ov", "config.yml"))
		paths = append(paths, filepath.Join(home, ".ov.yaml"), filepath.Join(home, ".ov.yml"))
	}
	return paths
}

func loadConfig() oviewer.Config {
	config := oviewer.NewConfig()
	if opt.cfgFile != "" {
		if err := oviewer.LoadConfigFile(&config, opt.cfgFile); err != nil {
			fmt.Fprintln(os.Stderr, "failed to read config file:", err)
		}
		return config
	}
	for _, p := range configPaths() {
		if _, err := os.Stat(p); err != nil {
			continue
		}
		if err := oviewer.LoadConfigFile(&config, p); err != nil {
			fmt.Fprintln(os.Stderr, "failed to read config file:", err)
		}
		break
	}
	return config
}

func run(cmd *cobra.Command, args []string) error {
	if opt.completion != "" {
		switch opt.completion {
		case "bash":
			return cmd.GenBashCompletion(os.Stdout)
		case "zsh":
			return cmd.GenZshCompletion(os.Stdout)
		case "fish":
			return cmd.GenFishCompletion(os.Stdout, true)
		case "powershell":
			return cmd.GenPowerShellCompletionWithDesc(os.Stdout)
		}
		return errors.New("requires one of the arguments bash/zsh/fish/powershell")
	}

	config := loadConfig()

	if opt.helpKey {
		kb := oviewer.GetKeyBinds(config)
		fmt.Fprintln(os.Stdout, "ov is a feature rich pager")
		fmt.Fprint(os.Stdout, oviewer.KeyBindString(kb))
		fmt.Fprintln(os.Stdout)
		return nil
	}
	if opt.listViewModes {
		fmt.Fprintln(os.Stdout, "general")
		names := make([]string, 0, len(config.Mode))
		for name := range config.Mode {
			names = append(names, name)
		}
		sort.Strings(names)
		for _, name := range names {
			fmt.Fprintln(os.Stdout, name)
		}
		return nil
	}

	applyFlags(cmd, &config)

	stdoutTerm := term.IsTerminal(int(os.Stdout.Fd()))
	if !stdoutTerm && !opt.forceScreen {
		return passThrough(args)
	}

	ov := &oviewer.Options{
		Config:      config,
		Args:        args,
		Exec:        opt.execCommand,
		ViewMode:    opt.viewMode,
		Pattern:     opt.pattern,
		Filter:      opt.filter,
		NonMatch:    opt.nonMatchFilter,
		StdoutIsTTY: stdoutTerm,
	}
	return oviewer.Run(ov)
}

func passThrough(args []string) error {
	if len(args) == 0 {
		if term.IsTerminal(int(os.Stdin.Fd())) {
			return errors.New("missing file")
		}
		_, err := io.Copy(os.Stdout, os.Stdin)
		return err
	}
	f, err := os.Open(args[0])
	if err != nil {
		return err
	}
	defer f.Close()
	_, err = io.Copy(os.Stdout, f)
	return err
}

