	d.mu.Lock()
	if len(d.partial) > 0 {
		line := d.partial
		if len(line) > 0 && line[len(line)-1] == '\r' {
			line = line[:len(line)-1]
		}
		d.lines = append(d.lines, string(line))
		d.partial = nil
	}
	d.mu.Unlock()
