func splitLines(data []byte) []string {
	if len(data) == 0 {
		return []string{}
	}
	s := string(data)
	parts := strings.Split(s, "\n")
	if len(parts) > 0 && parts[len(parts)-1] == "" {
		parts = parts[:len(parts)-1]
	}
	for i, p := range parts {
		if len(p) > 0 && p[len(p)-1] == '\r' {
			parts[i] = p[:len(p)-1]
		}
	}
	return parts
}

// openFileDocument opens a file document.
func openFileDocument(name string, skipExtract bool) (*Document, error) {
	f, err := os.Open(name)
	if err != nil {
		return nil, err
	}
	fi, err := f.Stat()
	if err != nil {
		f.Close()
		return nil, err
	}
	if fi.IsDir() {
		f.Close()
		return nil, &os.PathError{Op: "read", Path: name, Err: errIsDir}
	}
	d := newDocument()
	d.FileName = name
	d.file = f
	data, err := io.ReadAll(f)
	f.Close()
	if err != nil {
		return nil, err
	}
	d.size = int64(len(data))
	d.offset = int64(len(data))
	if !skipExtract {
		if dec, ok := decompress(data); ok {
			data = dec
			d.compressed = true
		}
	}
	d.loadBytes(data)
	return d, nil
}

// reloadFile re-reads a file.
func (d *Document) reloadFile(skipExtract bool) error {
	data, err := os.ReadFile(d.FileName)
	if err != nil {
		return err
	}
	d.size = int64(len(data))
	d.offset = int64(len(data))
	if !skipExtract {
		if dec, ok := decompress(data); ok {
			data = dec
		}
	}
	d.loadBytes(data)
	return nil
}

// followFile checks for appended content.
func (d *Document) followFile() bool {
	if d.FileName == "" || d.isStdin || d.isExec || d.compressed {
		return false
	}
	f, err := os.Open(d.FileName)
	if err != nil {
		return false
	}
	defer f.Close()
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	if fi.Size() < d.offset {
		// truncated
		data, err := io.ReadAll(f)
		if err != nil {
			return false
		}
		d.offset = int64(len(data))
		d.size = d.offset
		d.loadBytes(data)
		return true
	}
	if fi.Size() == d.offset {
		return false
	}
	if _, err := f.Seek(d.offset, io.SeekStart); err != nil {
		return false
	}
	data, err := io.ReadAll(f)
	if err != nil || len(data) == 0 {
		return false
	}
	d.offset += int64(len(data))
	d.size = d.offset
	d.mu.Lock()
	// re-open partial line
	if len(d.partial) == 0 && d.eof && len(d.lines) > 0 && d.lastLineNoNL {
		d.partial = []byte(d.lines[len(d.lines)-1])
		d.lines = d.lines[:len(d.lines)-1]
		delete(d.cache, len(d.lines))
	}
	d.mu.Unlock()
	d.appendData(data)
	d.mu.Lock()
	d.lastLineNoNL = len(d.partial) > 0
	d.mu.Unlock()
	d.finishPartial()
	return true
}

type dirError struct{}

func (dirError) Error() string { return "is a directory" }

var errIsDir = dirError{}

// stdin document
func openStdinDocument(notify func()) *Document {
	d := newDocument()
	d.FileName = "(STDIN)"
	d.isStdin = true
	d.notify = notify
	d.readFrom(os.Stdin, false, nil)
	return d
}

// exec documents
func openExecDocuments(args []string, notify func()) ([]*Document, *exec.Cmd, error) {
	cmd := exec.Command(args[0], args[1:]...)
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return nil, nil, err
	}
	stderr, err := cmd.StderrPipe()
	if err != nil {
		return nil, nil, err
	}
	if err := cmd.Start(); err != nil {
		return nil, nil, err
	}
	name := strings.Join(args, " ")
	dout := newDocument()
	dout.FileName = "STDOUT"
	dout.isExec = true
	dout.execName = name
	dout.notify = notify
	derr := newDocument()
	derr.FileName = "STDERR"
	derr.isExec = true
	derr.execName = name
	derr.notify = notify
	var wg sync.WaitGroup
	wg.Add(2)
	dout.readFrom(stdout, false, wg.Done)
	derr.readFrom(stderr, false, wg.Done)
	go func() {
		wg.Wait()
		_ = cmd.Wait()
		notify()
	}()
	return []*Document{dout, derr}, cmd, nil
}
