	root.inputKeys = newKeyMatcher(root.keyBind, inputActionNames())

	notify := root.requestUpdate
	if opts.Exec {
		if len(opts.Args) == 0 {
			return errors.New("missing command")
		}
		docs, cmd, err := openExecDocuments(opts.Args, notify)
		if err != nil {
			return err
		}
		root.cmd = cmd
		root.docs = docs
	} else if len(opts.Args) == 0 {
		if isTerminal(os.Stdin) {
			return errors.New("missing file")
