		for _, name := range opts.Args {
			d, err := openFileDocument(name, opts.Config.SkipExtract)
			if err != nil {
				fmt.Fprintln(os.Stderr, err)
				continue
			}
			d.notify = notify
			root.docs = append(root.docs, d)
