		d.watchInterval = g.WatchInterval
	}
	d.plain = g.PlainMode
	d.conv = convES
	switch {
	case g.Raw:
		d.conv = convRaw
	case g.Converter == "raw":
		d.conv = convRaw
	}
	if g.Converter == "align" || g.Align {
		d.General.Align = true
	}
