	}
	d.sectionDelimReg = re
}

func (d *Document) setMultiColor(words []string) {
	d.General.MultiColorWords = words
	d.multiColorRegs = nil
	for _, w := range words {
		if w == "" {
			continue
		}
		re, err := regexp.Compile(w)
		if err != nil {
			re = regexp.MustCompile(regexp.QuoteMeta(w))
		}
		d.multiColorRegs = append(d.multiColorRegs, re)
	}
}

func (d *Document) setJumpTarget(s string) {
	d.General.JumpTarget = s
	d.jumpTargetNum = 0
	d.jumpTargetSection = false
	d.jumpTargetSpec = strings.TrimSpace(s)
	if d.jumpTargetSpec == "section" {
		d.jumpTargetSection = true
	}
}

func isTerminal(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	return fi.Mode()&os.ModeCharDevice != 0
}

func (root *Root) requestUpdate() {
	root.updateMu.Lock()
	if root.updatePending {
		root.updateMu.Unlock()
		return
	}
	root.updatePending = true
	root.updateMu.Unlock()
	if root.screen != nil {
		ev := &eventUpdate{}
		ev.SetEventNow()
		_ = root.screen.PostEvent(ev)
	}
}

func (root *Root) main() error {
	screen, err := tcell.NewScreen()
	if err != nil {
		return err
	}
	if err := screen.Init(); err != nil {
		return err
	}
	root.screen = screen
	if !root.config.DisableMouse {
		screen.EnableMouse(tcell.MouseButtonEvents)
		root.mouseEnabled = true
	}
	screen.EnablePaste()
	root.width, root.height = screen.Size()

	// wait briefly for initial data
	root.waitInitial()

	for _, d := range root.docs {
		root.initPosition(d)
	}

	if root.config.QuitSmall && root.fitsOneScreen() {
		screen.Fini()
		root.writeAll(os.Stdout)
		return nil
	}

	root.startTimers()
	if root.opts.Pattern != "" {
		root.setSearchWord(root.opts.Pattern)
		root.searchForward(root.doc.topLN, false)
	}
	if root.opts.Filter != "" {
		root.filter(root.opts.Filter, false)
	}
	if root.opts.NonMatchPat != "" {
		root.filter(root.opts.NonMatchPat, true)
	}

	root.draw()
	for !root.quit {
		ev := screen.PollEvent()
		if ev == nil {
			break
		}
		root.handleEvent(ev)
		if root.quit {
			break
		}
		for screen.HasPendingEvent() && !root.quit {
			ev = screen.PollEvent()
			if ev == nil {
				break
			}
			root.handleEvent(ev)
		}
		if root.quit {
			break
		}
		root.draw()
	}
	root.finish()
	return nil
}

func (root *Root) waitInitial() {
	deadline := time.Now().Add(300 * time.Millisecond)
	for time.Now().Before(deadline) {
		all := true
		for _, d := range root.docs {
			if !d.BufEOF() {
				all = false
			}
		}
		if all {
			return
		}
		time.Sleep(5 * time.Millisecond)
	}
}

func (root *Root) initPosition(d *Document) {
	d.topLN = d.firstBodyLine()
	if d.followMode || d.followAll || d.followSection {
		root.withDoc(d, func() { root.moveBottomFollow() })
	}
}

func (root *Root) withDoc(d *Document, f func()) {
	save := root.doc
	root.doc = d
	f()
	root.doc = save
}

func (d *Document) firstBodyLine() int {
	n := d.General.Header + d.General.SkipLines
	if n < 0 {
		n = 0
	}
	return n
}

func (root *Root) handleEvent(ev tcell.Event) {
	switch e := ev.(type) {
	case *eventUpdate:
		root.updateMu.Lock()
		root.updatePending = false
		root.updateMu.Unlock()
		root.onUpdate()
	case *eventTimer:
		root.onTimer(e.id)
	case *tcell.EventResize:
		root.width, root.height = root.screen.Size()
		root.screen.Sync()
	case *tcell.EventKey:
		root.handleKey(e)
	case *tcell.EventMouse:
		root.handleMouse(e)
	case *tcell.EventPaste:
	}
}

func (root *Root) handleKey(ev *tcell.EventKey) {
	if root.input != nil {
		root.inputKey(ev)
		return
	}
	root.message = ""
	action := root.keys.match(ev)
	if action == "" {
		return
	}
	root.doAction(action)
}

func (root *Root) handleMouse(ev *tcell.EventMouse) {
	b := ev.Buttons()
	n := root.doc.General.VScrollLines
	if n <= 0 {
		n = 2
	}
	if b&tcell.WheelUp != 0 {
		root.moveUpRows(n)
	} else if b&tcell.WheelDown != 0 {
		root.moveDownRows(n)
	}
}

func (root *Root) setMessage(msg string) {
	root.message = msg
	root.logs = append(root.logs, msg)
}

func (root *Root) setMessagef(format string, a ...interface{}) {
	root.setMessage(fmt.Sprintf(format, a...))
}

func (root *Root) finish() {
	root.stopTimers()
	var out []string
	if root.writeOnExit {
		out = root.screenLines()
	}
	root.screen.Fini()
	if root.cmd != nil && root.cmd.Process != nil {
		_ = root.cmd.Process.Kill()
	}
	for _, l := range out {
		fmt.Fprintln(os.Stdout, l)
	}
}

func atoiDefault(s string, def int) int {
	n, err := strconv.Atoi(strings.TrimSpace(s))
	if err != nil {
		return def
	}
	return n
}
