func (root *Root) withDoc(d *Document, f func()) {
	save := root.doc
	root.doc = d
	f()
	root.doc = save
}

func (d *Document) firstBodyLine() int {
	n := d.General.Header + d.General.SkipLines
	if n < 0 {
		n = 0
	}
	return n
}

func (root *Root) handleEvent(ev tcell.Event) {
	switch e := ev.(type) {
	case *eventUpdate:
		root.updateMu.Lock()
		root.updatePending = false
		root.updateMu.Unlock()
		root.onUpdate()
	case *eventTimer:
		root.onTimer(e.id)
	case *tcell.EventResize:
		root.width, root.height = root.screen.Size()
		root.screen.Sync()
	case *tcell.EventKey:
		root.handleKey(e)
	case *tcell.EventMouse:
		root.handleMouse(e)
	case *tcell.EventPaste:
	}
}

func (root *Root) handleKey(ev *tcell.EventKey) {
	if root.input != nil {
		root.inputKey(ev)
		return
	}
	root.message = ""
	action := root.keys.match(ev)
	if action == "" {
		return
	}
	root.doAction(action)
}

func (root *Root) handleMouse(ev *tcell.EventMouse) {
	b := ev.Buttons()
	n := root.doc.General.VScrollLines
	if n <= 0 {
		n = 2
	}
	if b&tcell.WheelUp != 0 {
		root.moveUpRows(n)
	} else if b&tcell.WheelDown != 0 {
		root.moveDownRows(n)
	}
}

func (root *Root) setMessage(msg string) {
	root.message = msg
	root.logs = append(root.logs, msg)
}

func (root *Root) setMessagef(format string, a ...interface{}) {
	root.setMessage(fmt.Sprintf(format, a...))
}

func (root *Root) finish() {
	root.stopTimers()
	var out []string
	if root.writeOnExit {
		out = root.screenLines()
	}
	root.screen.Fini()
	if root.cmd != nil && root.cmd.Process != nil {
		_ = root.cmd.Process.Kill()
	}
	for _, l := range out {
		fmt.Fprintln(os.Stdout, l)
	}
}

func atoiDefault(s string, def int) int {
	n, err := strconv.Atoi(strings.TrimSpace(s))
	if err != nil {
		return def
	}
	return n
}
EOF
