// contentsOf returns parsed contents of line n.
func (root *Root) contentsOf(d *Document, n int) contents {
	d.mu.RLock()
	if lc, ok := d.cache[n]; ok && d.cacheTW == d.General.TabWidth {
		d.mu.RUnlock()
		return lc
	}
	var line string
	ok := n >= 0 && n < len(d.lines)
	if ok {
		line = d.lines[n]
	}
	d.mu.RUnlock()
	if !ok {
		return nil
	}
