	if d.General.Align && d.alignInfo != nil {
		lc = root.alignContents(d, n, lc)
	}
	d.mu.Lock()
	if d.cacheTW != d.General.TabWidth {
		d.cache = map[int]contents{}
		d.cacheTW = d.General.TabWidth
	}
	if len(d.cache) > 20000 {
		d.cache = map[int]contents{}
	}
	d.cache[n] = lc
	d.mu.Unlock()
	return lc
}

// nextBreak returns the end index of a wrapped row starting at lx.
func nextBreak(lc contents, lx int, w int) int {
	if w <= 0 {
		return len(lc)
	}
	end := lx + w
	if end >= len(lc) {
		return len(lc)
	}
	// wide char that does not fit
	if lc[end].width == 0 && lc[end].mainc == 0 && end-1 > lx && lc[end-1].width == 2 {
		end--
	}
	return end
}

// wrapStarts returns row start positions of a line.
func wrapStarts(lc contents, w int) []int {
	starts := []int{0}
	if w <= 0 {
		return starts
	}
	lx := 0
	for {
		end := nextBreak(lc, lx, w)
		if end >= len(lc) {
			break
		}
		starts = append(starts, end)
		lx = end
	}
	return starts
}

func (root *Root) lineNumWidth(d *Document) int {
	if !d.General.LineNumMode {
		return 0
	}
	n := d.BufEndNum()
	return len(strconv.Itoa(n)) + 1
}

// contentWidth returns the width available for line contents.
func (root *Root) contentWidth(d *Document) int {
	w := root.width - root.lineNumWidth(d) - root.sidebarWidth()
	if w < 1 {
		w = 1
	}
	return w
}

func (root *Root) sidebarWidth() int {
	if root.sidebar == sidebarNone {
		return 0
	}
	if root.width < sidebarWidth*2 {
		return 0
	}
	return sidebarWidth
}

// rowsOfLine returns row count of a line.
func (root *Root) rowsOfLine(d *Document, n int) int {
	if !d.General.WrapMode {
		return 1
	}
	lc := root.contentsOf(d, n)
	return len(wrapStarts(lc, root.contentWidth(d)))
}

func (root *Root) statusHeight(d *Document) int {
	if d.General.StatusLine {
		return 1
	}
	return 0
}

func (root *Root) rulerHeight(d *Document) int {
	if d.General.RulerType != 0 {
		return 2
	}
	return 0
}

// headerLines returns header line range.
func (d *Document) headerRange() (int, int) {
	start := d.General.SkipLines
	if start < 0 {
		start = 0
	}
	end := start + d.General.Header
	n := d.BufEndNum()
	if end > n {
		end = n
	}
	if start > end {
		start = end
	}
	return start, end
}

// sectionStartOf returns the section delimiter line for line n (-1 if none).
func (root *Root) sectionStartOf(d *Document, n int) int {
	if d.sectionDelimReg == nil {
		return -1
	}
	_, hend := d.headerRange()
	for i := n; i >= hend && i >= 0; i-- {
		s, ok := d.LineString(i)
		if !ok {
			continue
		}
		if d.sectionDelimReg.MatchString(stripEscapes(s)) {
			return i + d.General.SectionStartPosition
		}
	}
	return -1
}

func (d *Document) isSectionLine(root *Root, n int) bool {
	if d.sectionDelimReg == nil {
		return false
	}
	ln := n - d.General.SectionStartPosition
	s, ok := d.LineString(ln)
	if !ok {
		return false
	}
	return d.sectionDelimReg.MatchString(stripEscapes(s))
}

func (root *Root) computeLayout(d *Document) *layout {
	ly := &layout{width: root.width, height: root.height}
	ly.statusY = root.height - root.statusHeight(d)
	ly.numW = root.lineNumWidth(d)
	ly.sidebarW = root.sidebarWidth()
	ly.startX = ly.sidebarW
	ly.contentW = root.contentWidth(d)
	ly.rulerRows = root.rulerHeight(d)
	y := ly.rulerRows
	wrap := d.General.WrapMode
	// header
	hs, he := d.headerRange()
	for ln := hs; ln < he && y < ly.statusY; ln++ {
		lc := root.contentsOf(d, ln)
		if wrap {
			starts := wrapStarts(lc, ly.contentW)
			for i, s := range starts {
				if y >= ly.statusY {
					break
				}
				end := len(lc)
				if i+1 < len(starts) {
					end = starts[i+1]
				}
				ly.headerRows = append(ly.headerRows, rowSpec{ln: ln, lx: s, end: end, y: y, first: i == 0})
				y++
			}
		} else {
			ly.headerRows = append(ly.headerRows, rowSpec{ln: ln, lx: 0, end: len(lc), y: y, first: true})
			y++
		}
	}
	ly.bodyY = y
	ly.bodyHeight = ly.statusY - y
	// section header
	ly.sectionStart = -1
	if d.sectionDelimReg != nil && d.General.SectionHeaderNum > 0 {
		ss := root.sectionStartOf(d, d.topLN)
		if ss >= 0 && ss <= d.topLN {
			ly.sectionStart = ss
			num := d.General.SectionHeaderNum
			for ln := ss; ln < ss+num && ln < d.BufEndNum() && y < ly.statusY; ln++ {
				lc := root.contentsOf(d, ln)
				if wrap {
					starts := wrapStarts(lc, ly.contentW)
					for i, s := range starts {
						if y >= ly.statusY {
							break
						}
						end := len(lc)
						if i+1 < len(starts) {
							end = starts[i+1]
						}
						ly.sectionRows = append(ly.sectionRows, rowSpec{ln: ln, lx: s, end: end, y: y, first: i == 0})
						y++
					}
				} else {
					ly.sectionRows = append(ly.sectionRows, rowSpec{ln: ln, lx: 0, end: len(lc), y: y, first: true})
					y++
				}
			}
			ly.hidden = len(ly.sectionRows)
		}
	}
	// body
	ln := d.topLN
	lx := d.topLX
	total := d.BufEndNum()
	skip := ly.hidden
	for yy := ly.bodyY; yy < ly.statusY; {
		if ln >= total || ln < 0 {
			if skip > 0 {
				skip--
				continue
			}
			ly.bodyRows = append(ly.bodyRows, rowSpec{ln: -1, y: yy})
			yy++
			continue
		}
		lc := root.contentsOf(d, ln)
		var end int
		if wrap {
			if lx > 0 && lx >= len(lc) {
				ln++
				lx = 0
				continue
			}
			end = nextBreak(lc, lx, ly.contentW)
		} else {
			lx = 0
			end = len(lc)
		}
		if skip > 0 {
			skip--
		} else {
			ly.bodyRows = append(ly.bodyRows, rowSpec{ln: ln, lx: lx, end: end, y: yy, first: lx == 0})
			yy++
		}
		if !wrap || end >= len(lc) {
			ln++
			lx = 0
		} else {
			lx = end
		}
	}
	return ly
}

func (root *Root) draw() {
	if root.screen == nil {
		return
	}
	d := root.doc
	root.width, root.height = root.screen.Size()
	ly := root.computeLayout(d)
	root.lastLayout = ly
	s := root.screen
	// clear
	for y := 0; y < root.height; y++ {
		for x := 0; x < root.width; x++ {
			s.SetContent(x, y, ' ', nil, tcell.StyleDefault)
		}
	}
	if ly.rulerRows > 0 {
		root.drawRuler(d, ly)
	}
	for _, r := range ly.headerRows {
		root.drawRow(d, ly, r, rowHeader)
	}
	for _, r := range ly.sectionRows {
		root.drawRow(d, ly, r, rowSectionHeader)
	}
	for _, r := range ly.bodyRows {
		if r.ln < 0 {
			root.drawEOF(d, ly, r.y)
			continue
		}
		root.drawRow(d, ly, r, rowBody)
	}
	if ly.sidebarW > 0 {
		root.drawSidebar(ly)
	}
	if ly.statusY < root.height {
		root.drawStatus(d, ly)
	} else {
		s.HideCursor()
	}
	s.Show()
}

const (
	rowHeader = iota
	rowSectionHeader
	rowBody
)

func (root *Root) drawEOF(d *Document, ly *layout, y int) {
	x := ly.startX + ly.numW
	root.screen.SetContent(x, y, '~', nil, tcell.StyleDefault.Foreground(tcell.ColorGray))
}

func (root *Root) drawRuler(d *Document, ly *layout) {
	st := ToTcellStyle(d.General.Style.Ruler)
	base := 0
	if !d.General.WrapMode {
		base = d.x
	}
	for c := 0; c < ly.width-ly.startX; c++ {
		v := base + c - ly.numW + 1
		x := ly.startX + c
		ch1 := ' '
		if v > 0 && v%10 == 0 {
			ch1 = rune('0' + (v/10)%10)
		}
		vv := v
		if vv < 0 {
			vv = 0
		}
		ch2 := rune('0' + vv%10)
		root.screen.SetContent(x, 0, ch1, nil, st)
		root.screen.SetContent(x, 1, ch2, nil, st)
	}
}

// cell buffer for a row
type rowCells []content

func (root *Root) drawRow(d *Document, ly *layout, r rowSpec, kind int) {
	lc := root.contentsOf(d, r.ln)
	w := ly.contentW
	cells := make(rowCells, w)
	for i := range cells {
		cells[i] = DefaultContent
	}
	// map row cells
	var from int
	if d.General.WrapMode {
		from = r.lx
		for i := 0; i < w && from+i < r.end; i++ {
			cells[i] = lc[from+i]
		}
	} else {
		from = d.x
		root.fillNoWrap(d, lc, cells, r.ln)
	}
	// styles
	switch kind {
	case rowHeader:
		root.decorateLine(d, r, lc, cells, from, false)
		hs := d.General.Style.Header
		for i := range cells {
			cells[i].style = applyStyle(cells[i].style, hs)
		}
	case rowSectionHeader:
		root.decorateLine(d, r, lc, cells, from, false)
		ss := d.General.Style.SectionLine
		for i := range cells {
			cells[i].style = applyStyle(cells[i].style, ss)
		}
	default:
		root.decorateLine(d, r, lc, cells, from, true)
	}
	// draw line number
	x := ly.startX
	if ly.numW > 0 {
		numStyle := ToTcellStyle(d.General.Style.LineNumber)
		if kind == rowBody {
			num := r.ln - d.firstBodyLine() + 1
			str := strconv.Itoa(num)
			pad := ly.numW - 1 - len(str)
			s := ""
			for i := 0; i < pad; i++ {
				s += " "
			}
			s += str + " "
			for i, c := range s {
				root.screen.SetContent(x+i, r.y, c, nil, numStyle)
			}
		}
		x += ly.numW
	}
	root.putCells(x, r.y, cells)
}

func (root *Root) putCells(x, y int, cells rowCells) {
	for i := 0; i < len(cells); i++ {
		c := cells[i]
		if c.width == 0 && c.mainc == 0 {
			// right half of wide char drawn by left half; if orphan, draw space
			if i == 0 || cells[i-1].width != 2 {
				root.screen.SetContent(x+i, y, ' ', nil, c.style)
			}
			continue
		}
		if c.width == 2 && i == len(cells)-1 {
			root.screen.SetContent(x+i, y, ' ', nil, c.style)
			continue
		}
		mc := c.mainc
		if c.width == 0 {
			mc = ' '
			root.screen.SetContent(x+i, y, mc, nil, c.style)
			continue
		}
		root.screen.SetContent(x+i, y, mc, c.combc, c.style)
	}
}

// fillNoWrap fills cells for no-wrap mode taking vertical header into account.
func (root *Root) fillNoWrap(d *Document, lc contents, cells rowCells, ln int) {
	w := len(cells)
	vh := root.verticalHeaderWidth(d, ln, lc)
	if vh > w {
		vh = w
	}
	i := 0
	for ; i < vh && i < len(lc); i++ {
		cells[i] = lc[i]
	}
	if vh > 0 {
		i = vh
	}
	start := d.x + vh
	if d.General.HeaderColumn > 0 || d.General.VerticalHeader > 0 {
		start = d.x + vh
	}
	for j := 0; i < w; i, j = i+1, j+1 {
		idx := start + j
		if idx < len(lc) {
			cells[i] = lc[idx]
		}
	}
}

func (root *Root) verticalHeaderWidth(d *Document, ln int, lc contents) int {
	if d.General.VerticalHeader > 0 {
		return d.General.VerticalHeader
	}
	if d.General.HeaderColumn > 0 && d.General.ColumnMode {
		cols := root.columnRanges(d, ln, lc)
		n := d.General.HeaderColumn
		if n > len(cols) {
			n = len(cols)
		}
		if n == 0 {
			return 0
		}
		return cols[n-1].end + 1
	}
	return 0
}

// cellIndexRange maps content index range to cell positions in the row.
func rowPos(d *Document, from int, idx int, vh int) int {
	if d.General.WrapMode {
		return idx - from
	}
	if idx < vh {
		return idx
	}
	return idx - d.x
}

func (root *Root) decorateLine(d *Document, r rowSpec, lc contents, cells rowCells, from int, body bool) {
	g := &d.General
	vh := 0
	if !g.WrapMode {
		vh = root.verticalHeaderWidth(d, r.ln, lc)
	}
	apply := func(start, end int, s OVStyle) {
		for idx := start; idx < end; idx++ {
			p := rowPos(d, from, idx, vh)
			if !g.WrapMode && idx >= vh && idx-d.x < vh {
				continue
			}
			if p < 0 || p >= len(cells) {
				continue
			}
			cells[p].style = applyStyle(cells[p].style, s)
		}
	}
	if body {
		if g.Style.Body != (OVStyle{}) {
			for i := range cells {
				cells[i].style = applyStyle(cells[i].style, g.Style.Body)
			}
		}
		if d.isSectionLine(root, r.ln) {
			for i := range cells {
				cells[i].style = applyStyle(cells[i].style, g.Style.SectionLine)
			}
		}
		if g.AlternateRows && r.ln%2 == 1 {
			for i := range cells {
				cells[i].style = applyStyle(cells[i].style, g.Style.Alternate)
			}
		}
	}
	// column mode
	if g.ColumnMode {
		cols := root.columnRanges(d, r.ln, lc)
		if g.ColumnRainbow && len(g.Style.ColumnRainbow) > 0 {
			for i, c := range cols {
				apply(c.start, c.end, g.Style.ColumnRainbow[i%len(g.Style.ColumnRainbow)])
			}
		}
		if body || true {
			cur := d.columnCursor
			if cur >= 0 && cur < len(cols) {
				apply(cols[cur].start, cols[cur].end, g.Style.ColumnHighlight)
			}
		}
	}
	// multi color
	if len(d.multiColorRegs) > 0 && len(g.Style.MultiColorHighlight) > 0 {
		str, pos := contentsToString(lc)
		for i, re := range d.multiColorRegs {
			st := g.Style.MultiColorHighlight[i%len(g.Style.MultiColorHighlight)]
			for _, m := range re.FindAllStringIndex(str, -1) {
				if m[0] == m[1] {
					continue
				}
				apply(pos[m[0]], pos[m[1]], st)
			}
		}
	}
	// search
	if root.searcher != nil {
		str, pos := contentsToString(lc)
		for _, m := range root.searcher.FindAll(str) {
			if m[0] == m[1] {
				continue
			}
			apply(pos[m[0]], pos[m[1]], g.Style.SearchHighlight)
		}
	}
	if body {
		// mark
		if d.isMarked(r.ln) {
			n := g.MarkStyleWidth
			if n <= 0 {
				n = 1
			}
			for i := 0; i < n && i < len(cells); i++ {
				cells[i].style = applyStyle(cells[i].style, g.Style.MarkLine)
			}
		}
		// jump target
		if d.General.JumpTarget != "" {
			ly := root.lastLayoutFor()
			if ly != nil {
				jt := root.jumpTargetRow(d, ly)
				if jt >= 0 && r.y == ly.bodyY+jt {
					for i := range cells {
						cells[i].style = applyStyle(cells[i].style, g.Style.JumpTargetLine)
					}
				}
			}
		}
	}
}

func (root *Root) lastLayoutFor() *layout {
	return root.lastLayout
}
EOF
echo ok"}

