{"command":"cat > /workspace/oviewer/move.go <<'EOF'
package oviewer

import (
	"strconv"
	"strings"
)

type pos struct {
	ln, lx int
}

func posLess(a, b pos) bool {
	if a.ln != b.ln {
		return a.ln < b.ln
	}
	return a.lx < b.lx
}

func (root *Root) rowStartsOf(d *Document, ln int) []int {
	if !d.General.WrapMode {
		return []int{0}
	}
	lc := root.contentsOf(d, ln)
	return wrapStarts(lc, root.contentWidth(d))
}

// nextRow returns the next row position.
func (root *Root) nextRow(d *Document, p pos) (pos, bool) {
	total := d.BufEndNum()
	if p.ln >= total {
		return p, false
	}
	starts := root.rowStartsOf(d, p.ln)
	for i, s := range starts {
		if s > p.lx {
			return pos{p.ln, starts[i]}, true
		}
	}
	if p.ln+1 > total {
		return p, false
	}
	return pos{p.ln + 1, 0}, true
}

// prevRow returns the previous row position.
func (root *Root) prevRow(d *Document, p pos) (pos, bool) {
	if p.lx > 0 {
		starts := root.rowStartsOf(d, p.ln)
		prev := 0
		for _, s := range starts {
			if s >= p.lx {
				break
			}
			prev = s
		}
		return pos{p.ln, prev}, true
	}
	if p.ln-1 < 0 {
		return p, false
	}
	starts := root.rowStartsOf(d, p.ln-1)
	return pos{p.ln - 1, starts[len(starts)-1]}, true
}

func (root *Root) bodyHeight(d *Document) int {
	ly := root.computeLayoutLite(d)
	return ly
}

// computeLayoutLite returns body height (rows below header).
func (root *Root) computeLayoutLite(d *Document) int {
	h := root.height - root.statusHeight(d) - root.rulerHeight(d)
	hs, he := d.headerRange()
	rows := 0
	for ln := hs; ln < he; ln++ {
		rows += root.rowsOfLine(d, ln)
	}
	h -= rows
	if h < 1 {
		h = 1
	}
	return h
}

// bottomPos returns the position used for the end of document.
func (root *Root) bottomPos(d *Document) pos {
	total := d.BufEndNum()
	first := d.firstBodyLine()
	if total <= first {
		return pos{first, 0}
	}
	need := root.computeLayoutLite(d) - 1
	if need < 1 {
		need = 1
	}
	ln := total - 1
	starts := root.rowStartsOf(d, ln)
	p := pos{ln, starts[len(starts)-1]}
	for i := 1; i < need; i++ {
		np, ok := root.prevRow(d, p)
		if !ok || np.ln < first {
			break
		}
		p = np
	}
	return p
}

func (root *Root) curPos() pos {
	return pos{root.doc.topLN, root.doc.topLX}
}

func (root *Root) setPos(p pos) {
	root.doc.topLN = p.ln
	root.doc.topLX = p.lx
}

func (root *Root) moveDownRows(n int) {
	d := root.doc
	bottom := root.bottomPos(d)
	p := root.curPos()
	if !posLess(p, bottom) {
		return
	}
	for i := 0; i < n; i++ {
		np, ok := root.nextRow(d, p)
		if !ok {
			break
		}
		p = np
		if !posLess(p, bottom) {
			p = bottom
			break
		}
	}
	root.setPos(p)
}

func (root *Root) moveUpRows(n int) {
	d := root.doc
	first := d.firstBodyLine()
	p := root.curPos()
	for i := 0; i < n; i++ {
		if p.ln < first || (p.ln == first && p.lx == 0) {
			break
		}
		np, ok := root.prevRow(d, p)
		if !ok {
			break
		}
		if np.ln < first {
			np = pos{first, 0}
		}
		p = np
	}
	if p.ln < first {
		p = pos{first, 0}
	}
	root.setPos(p)
}

func (root *Root) pageRows() int {
	n := root.height - 1
	if n < 1 {
		n = 1
	}
	return n
}

func (root *Root) moveTop() {
	root.setPos(pos{root.doc.firstBodyLine(), 0})
}

func (root *Root) moveBottom() {
	root.setPos(root.bottomPos(root.doc))
}

func (root *Root) moveBottomFollow() {
	root.setPos(root.bottomPos(root.doc))
}

// moveLine moves so that line n is the first visible body line.
func (root *Root) moveLine(n int) {
	d := root.doc
	total := d.BufEndNum()
	if n >= total {
		n = total - 1
	}
	first := d.firstBodyLine()
	if n < first {
		n = first
	}
	top := n
	if d.sectionDelimReg != nil && d.General.SectionHeaderNum > 0 {
		ss := root.sectionStartOf(d, n)
		if ss >= 0 && ss <= n {
			t := n - d.General.SectionHeaderNum
			if t < ss {
				t = ss
			}
			top = t
		}
	}
	if top < 0 {
		top = 0
	}
	root.setPos(pos{top, 0})
}

// currentLine returns the line at the first visible body row.
func (root *Root) currentLine() int {
	ly := root.computeLayout(root.doc)
	for _, r := range ly.bodyRows {
		if r.ln >= 0 {
			return r.ln
		}
		break
	}
	return root.doc.topLN
}

func (root *Root) gotoInput(s string) {
	d := root.doc
	s = strings.TrimSpace(s)
	if s == "" {
		return
	}
	total := d.BufEndNum()
	first := d.firstBodyLine()
	var n int
	if strings.HasSuffix(s, "%") {
		f, err := strconv.ParseFloat(strings.TrimSuffix(s, "%"), 64)
		if err != nil {
			root.setMessagef("Invalid line number: %s", s)
			return
		}
		n = int(float64(total) * f / 100)
	} else if strings.HasPrefix(s, ".") {
		f, err := strconv.ParseFloat("0"+s, 64)
		if err != nil {
			root.setMessagef("Invalid line number: %s", s)
			return
		}
		n = int(float64(total) * f)
	} else {
		v, err := strconv.Atoi(s)
		if err != nil {
			root.setMessagef("Invalid line number: %s", s)
			return
		}
		n = v
		if n < 1 {
			n = 1
		}
		if n+first > total {
			n = total - first
		}
	}
	if n < 1 {
		n = 1
	}
	ln := n - 1 + first
	if strings.HasSuffix(s, "%") || strings.HasPrefix(s, ".") {
		ln = n - 1
		if ln < first {
			ln = first
		}
		n = ln - first + 1
	}
	root.moveLine(ln)
	root.setMessagef("Moved to line %d", n)
}

// horizontal
func (root *Root) moveRight(n int) {
	d := root.doc
	if d.General.WrapMode {
		return
	}
	d.x += n
}

func (root *Root) moveLeft(n int) {
	d := root.doc
	if d.General.WrapMode {
		return
	}
	d.x -= n
	if d.x < 0 {
		d.x = 0
	}
}

func (root *Root) hscrollWidth() int {
	s := strings.TrimSpace(root.doc.General.HScrollWidth)
	w := root.width
	if s == "" {
		return w / 10
	}
	if strings.HasSuffix(s, "%") {
		f, err := strconv.ParseFloat(strings.TrimSuffix(s, "%"), 64)
		if err == nil {
			return int(float64(w) * f / 100)
		}
	}
	if strings.HasPrefix(s, ".") {
		f, err := strconv.ParseFloat("0"+s, 64)
		if err == nil {
			return int(float64(w) * f)
		}
	}
	n, err := strconv.Atoi(s)
	if err == nil {
		return n
	}
	return w / 10
}

func (root *Root) maxVisibleWidth() int {
	d := root.doc
	ly := root.computeLayout(d)
	max := 0
	for _, r := range ly.headerRows {
		if l := len(root.contentsOf(d, r.ln)); l > max {
			max = l
		}
	}
	for _, r := range ly.bodyRows {
		if r.ln < 0 {
			continue
		}
		if l := len(root.contentsOf(d, r.ln)); l > max {
			max = l
		}
	}
	return max
}

func (root *Root) moveEndRight() {
	d := root.doc
	if d.General.WrapMode {
		return
	}
	max := root.maxVisibleWidth()
	x := max - root.contentWidth(d) + 2
	if x < 0 {
		x = 0
	}
	d.x = x
}
EOF
echo ok"}

