{"command":"cat > /workspace/oviewer/input.go <<'EOF'
package oviewer

import (
	"strings"
	"unicode/utf8"

	"github.com/gdamore/tcell/v2"
	"github.com/mattn/go-runewidth"
)

const (
	inputSearch = iota
	inputBackSearch
	inputFilter
	inputGoto
	inputHeader
	inputDelimiter
	inputTabWidth
	inputJumpTarget
	inputMultiColor
	inputSkipLines
	inputVerticalHeader
	inputHeaderColumn
	inputViewMode
	inputSectionDelimiter
	inputSectionStart
	inputSectionNum
	inputWatchInterval
	inputMarkNumber
	inputMarkPattern
	inputConvert
	inputSaveBuffer
)

type inputState struct {
	root       *Root
	mode       int
	buf        []rune
	cursor     int
	candidates []string
	candIdx    int
	nonMatch   bool
	origPos    pos
}

func (in *inputState) value() string {
	return string(in.buf)
}

func (in *inputState) cursorWidth() int {
	return runewidth.StringWidth(string(in.buf[:in.cursor]))
}

func (in *inputState) promptString() string {
	root := in.root
	flags := func() string {
		s := ""
		if root.regexpSearch {
			s += "(R)"
		}
		if root.incsearch {
			s += "(I)"
		}
		if root.smartCase {
			s += "(S)"
		} else if root.caseSensitive {
			s += "(Aa)"
		}
		return s
	}
	switch in.mode {
	case inputSearch:
		return flags() + "/"
	case inputBackSearch:
		return flags() + "?"
	case inputFilter:
		if in.nonMatch {
			return "Non-match&"
		}
		return "&"
	case inputGoto:
		return "Goto line:"
	case inputHeader:
		return "Header length:"
	case inputDelimiter:
		return "Delimiter:"
	case inputTabWidth:
		return "TAB width:"
	case inputJumpTarget:
		return "Jump target line:"
	case inputMultiColor:
		return "Multi color:"
	case inputSkipLines:
		return "Skip lines:"
	case inputVerticalHeader:
		return "Vertical header length:"
	case inputHeaderColumn:
		return "Header column:"
	case inputViewMode:
		return "Mode:"
	case inputSectionDelimiter:
		return "Section delimiter:"
	case inputSectionStart:
		return "Section start:"
	case inputSectionNum:
		return "Section Num:"
	case inputWatchInterval:
		return "Watch interval:"
	case inputMarkNumber:
		return "Mark number:"
	case inputMarkPattern:
		return "*"
	case inputConvert:
		return "Convert:"
	case inputSaveBuffer:
		return "(Save)file:"
	}
	return ""
}

func (root *Root) startInput(mode int, candidates []string) {
	in := &inputState{root: root, mode: mode, candidates: candidates, origPos: root.curPos()}
	in.candIdx = len(candidates)
	root.input = in
}

func (in *inputState) setValue(s string) {
	in.buf = []rune(s)
	in.cursor = len(in.buf)
}

func (root *Root) inputKey(ev *tcell.EventKey) {
	in := root.input
	action := root.inputKeys.match(ev)
	isSearch := in.mode == inputSearch || in.mode == inputBackSearch || in.mode == inputFilter || in.mode == inputMarkPattern
	switch action {
	case "input_casesensitive":
		if isSearch {
			root.caseSensitive = !root.caseSensitive
			if root.caseSensitive {
				root.smartCase = false
			}
			root.incSearch()
			return
		}
	case "input_smart_casesensitive":
		if isSearch {
			root.smartCase = !root.smartCase
			root.incSearch()
			return
		}
	case "input_regexp_search":
		if isSearch {
			root.regexpSearch = !root.regexpSearch
			root.incSearch()
			return
		}
	case "input_incsearch":
		if isSearch {
			root.incsearch = !root.incsearch
			return
		}
	case "input_non_match":
		if in.mode == inputFilter {
			in.nonMatch = !in.nonMatch
			return
		}
	case "input_previous":
		in.prevCandidate()
		root.incSearch()
		return
	case "input_next":
		in.nextCandidate()
		root.incSearch()
		return
	case "input_copy":
		return
	case "input_paste":
		return
	}
	switch ev.Key() {
	case tcell.KeyEscape:
		root.cancelInput()
		return
	case tcell.KeyEnter:
		root.confirmInput()
		return
	case tcell.KeyBackspace, tcell.KeyBackspace2:
		if in.cursor > 0 {
			in.buf = append(in.buf[:in.cursor-1], in.buf[in.cursor:]...)
			in.cursor--
			root.incSearch()
		} else if len(in.buf) == 0 {
			root.cancelInput()
		}
		return
	case tcell.KeyDelete:
		if in.cursor < len(in.buf) {
			in.buf = append(in.buf[:in.cursor], in.buf[in.cursor+1:]...)
			root.incSearch()
		}
		return
	case tcell.KeyLeft:
		if in.cursor > 0 {
			in.cursor--
		}
		return
	case tcell.KeyRight:
		if in.cursor < len(in.buf) {
			in.cursor++
		}
		return
	case tcell.KeyHome, tcell.KeyCtrlA:
		in.cursor = 0
		return
	case tcell.KeyEnd, tcell.KeyCtrlE:
		in.cursor = len(in.buf)
		return
	case tcell.KeyCtrlU:
		in.buf = in.buf[in.cursor:]
		in.cursor = 0
		root.incSearch()
		return
	case tcell.KeyCtrlK:
		in.buf = in.buf[:in.cursor]
		root.incSearch()
		return
	case tcell.KeyTab:
		in.insert('\t')
		root.incSearch()
		return
	case tcell.KeyRune:
		in.insert(ev.Rune())
		root.incSearch()
		return
	}
}

func (in *inputState) insert(r rune) {
	nb := make([]rune, 0, len(in.buf)+1)
	nb = append(nb, in.buf[:in.cursor]...)
	nb = append(nb, r)
	nb = append(nb, in.buf[in.cursor:]...)
	in.buf = nb
	in.cursor++
}

func (in *inputState) prevCandidate() {
	if len(in.candidates) == 0 {
		return
	}
	in.candIdx--
	if in.candIdx < 0 {
		in.candIdx = len(in.candidates) - 1
	}
	in.setValue(in.candidates[in.candIdx])
}

func (in *inputState) nextCandidate() {
	if len(in.candidates) == 0 {
		return
	}
	in.candIdx++
	if in.candIdx >= len(in.candidates) {
		in.candIdx = 0
	}
	in.setValue(in.candidates[in.candIdx])
}

func (root *Root) cancelInput() {
	in := root.input
	root.input = nil
	if in.mode == inputMarkNumber {
		root.sidebar = sidebarNone
	}
}

func (root *Root) addHistory(mode int, s string) {
	if s == "" {
		return
	}
	key := mode
	if mode == inputBackSearch || mode == inputFilter || mode == inputMarkPattern {
		key = inputSearch
	}
	h := root.inputHistory[key]
	for i, v := range h {
		if v == s {
			h = append(h[:i], h[i+1:]...)
			break
		}
	}
	h = append(h, s)
	root.inputHistory[key] = h
}

