}

func (in *inputState) nextCandidate() {
	if len(in.candidates) == 0 {
		return
	}
	in.candIdx++
	if in.candIdx >= len(in.candidates) {
		in.candIdx = 0
	}
	in.setValue(in.candidates[in.candIdx])
}

