			if n >= total {
				continue
			}
			s, ok := root.lineSearchString(d, n)
			if ok && root.searcher.Match(s) {
				return n
			}
		}
		return -1
	}
	for n := start; n < total; n++ {
		if n < 0 {
			continue
		}
		s, ok := root.lineSearchString(d, n)
		if ok && root.searcher.Match(s) {
			return n
		}
	}
	return -1
}

func (root *Root) searchForward(start int, inc bool) {
	n := root.searchLine(start, false)
	if n < 0 {
		if !inc {
			root.setMessage("search:not found:" + root.searchWord)
		}
		return
	}
	root.jumpToMatch(n)
}

func (root *Root) searchBackward(start int, inc bool) {
	n := root.searchLine(start, true)
	if n < 0 {
		if !inc {
			root.setMessage("search:not found:" + root.searchWord)
		}
		return
	}
	root.jumpToMatch(n)
}

func (root *Root) jumpToMatch(n int) {
	d := root.doc
	jt := root.jumpTargetOffset(d, n)
	if jt > 0 {
		top := n
		for i := 0; i < jt; i++ {
			if top-1 < d.firstBodyLine() {
				break
			}
			top--
		}
		root.setPos(pos{top, 0})
		return
	}
	root.moveLine(n)
}

func (root *Root) nextSearch() {
	if root.searcher == nil {
		return
	}
	root.searchForward(root.doc.topLN+1, false)
}

func (root *Root) prevSearch() {
	if root.searcher == nil {
		return
	}
	root.searchBackward(root.doc.topLN-1, false)
}

// filter creates a filtered document.
func (root *Root) filter(word string, nonMatch bool) {
	root.setSearchWord(word)
	src := root.doc
	searcher := root.newSearcher(word)
	if searcher == nil {
		return
	}
	nd := newDocument()
	nd.General = src.General
	nd.isFilter = true
	nd.filterOf = src
	if nonMatch {
		nd.FileName = "filter:!" + word
	} else {
		nd.FileName = "filter:" + word
	}
	nd.Caption = ""
	var lines []string
	var lns []int
	total := src.BufEndNum()
	hs, he := src.headerRange()
	for n := hs; n < he; n++ {
		s, _ := src.LineString(n)
		lines = append(lines, s)
		lns = append(lns, n)
	}
	for n := he; n < total; n++ {
		s, ok := root.lineSearchString(src, n)
		if !ok {
			continue
		}
		m := searcher.Match(s)
		if m != nonMatch {
			raw, _ := src.LineString(n)
			lines = append(lines, raw)
			lns = append(lns, n)
		}
	}
	nd.General.SkipLines = 0
	nd.General.Header = he - hs
	nd.setLines(lines)
	nd.filterLN = lns
	root.applyGeneralFilter(nd, src)
	// insert after current
	idx := root.cur + 1
	root.docs = append(root.docs, nil)
	copy(root.docs[idx+1:], root.docs[idx:])
	root.docs[idx] = nd
	root.cur = idx
	root.doc = nd
	nd.topLN = nd.firstBodyLine()
	root.setMessage("search:" + word)
}

func (root *Root) applyGeneralFilter(nd, src *Document) {
	nd.followMode = false
	nd.plain = src.plain
	nd.conv = src.conv
	nd.sectionDelimReg = src.sectionDelimReg
	nd.multiColorRegs = src.multiColorRegs
	nd.jumpTargetSpec = src.jumpTargetSpec
	nd.jumpTargetSection = src.jumpTargetSection
	nd.cache = map[int]contents{}
}
EOF
