		d.alignInfo = nil
		root.prepareAlign(d)
		root.setMessage("Set align converter")
	case "raw":
		d.General.Align = false
		d.General.Converter = "raw"
		d.conv = convRaw
		root.setMessage("Set raw converter")
	case "es":
		d.General.Align = false
		d.General.Converter = "es"
		d.conv = convES
		root.setMessage("Set es converter")
	default:
		root.setMessage("invalid converter: " + name)
		return
	}
	d.clearCache()
}

func (root *Root) setConvertInput(v string) {
	root.setConverter(strings.TrimSpace(v))
}

func parseIntInput(v string) (int, error) {
	return strconv.Atoi(strings.TrimSpace(v))
}

func (root *Root) setHeaderInput(v string) {
	n, err := parseIntInput(v)
	if err != nil || n < 0 {
		root.setMessage("Set header lines: invalid number")
		return
	}
	d := root.doc
	d.General.Header = n
	if d.topLN < d.firstBodyLine() {
		d.topLN = d.firstBodyLine()
		d.topLX = 0
	}
	root.setMessagef("Set header lines %d", n)
}

func (root *Root) setSkipLinesInput(v string) {
