func (root *Root) setMultiColorInput(v string) {
	d := root.doc
	words := splitQuoted(v)
	d.setMultiColor(words)
	root.setMessagef("Set multicolor strings [%s]", strings.Join(words, " "))
}

func splitQuoted(s string) []string {
	var res []string
	var cur strings.Builder
	inQ := false
	has := false
	for _, r := range s {
		switch {
		case r == '"':
			inQ = !inQ
			has = true
		case r == ' ' && !inQ:
			if has || cur.Len() > 0 {
				res = append(res, cur.String())
			}
			cur.Reset()
			has = false
		default:
			cur.WriteRune(r)
		}
	}
	if has || cur.Len() > 0 {
		res = append(res, cur.String())
	}
	return res
}

func (root *Root) setVerticalHeaderInput(v string) {
	n, err := parseIntInput(v)
	if err != nil || n < 0 {
		root.setMessage("Set vertical header: invalid number")
		return
	}
	root.doc.General.VerticalHeader = n
	root.setMessagef("Set vertical header %d", n)
}

func (root *Root) setHeaderColumnInput(v string) {
	n, err := parseIntInput(v)
	if err != nil || n < 0 {
