	root.doc.General.HeaderColumn = n
	root.setMessagef("Set vertical header column %d", n)
}

func (root *Root) viewModeCandidates() []string {
	names := []string{"general"}
	var ms []string
	for name := range root.config.Mode {
		ms = append(ms, name)
	}
	sortStrings(ms)
	names = append(names, ms...)
	return names
}

func (root *Root) setViewModeInput(v string) {
	v = strings.TrimSpace(v)
	d := root.doc
	if v == "general" {
		root.reapplyGeneral(d, nil)
		root.setMessage("Set mode general")
		return
	}
	mm, ok := root.config.Mode[v]
	if !ok {
		root.setMessagef("%s mode not found", v)
		return
	}
	root.reapplyGeneral(d, mm)
	root.setMessagef("Set mode %s", v)
}

func (root *Root) reapplyGeneral(d *Document, mm map[string]interface{}) {
	g := root.config.General
	g.set = map[string]bool{}
	d.General = g
	if mm != nil {
		applyGeneralMap(&d.General, mm)
	}
	root.applyGeneral(d)
	if d.topLN < d.firstBodyLine() {
		d.topLN = d.firstBodyLine()
		d.topLX = 0
	}
}

func (root *Root) setSectionDelimiterInput(v string) {
	d := root.doc
	d.setSectionDelimiter(v)
	root.setMessagef("Set section delimiter %s", v)
}

func (root *Root) setSectionStartInput(v string) {
	n, err := parseIntInput(v)
	if err != nil {
		root.setMessage("Set section start position: invalid number")
		return
	}
	root.doc.General.SectionStartPosition = n
	root.setMessagef("Set section start position %d", n)
}

func (root *Root) setSectionNumInput(v string) {
	n, err := parseIntInput(v)
	if err != nil || n < 0 {
		root.setMessage("Set section header num: invalid number")
		return
	}
	root.doc.General.SectionHeaderNum = n
	root.setMessagef("Set section header num %d", n)
}

func (root *Root) setWatchIntervalInput(v string) {
	n, err := parseIntInput(v)
	if err != nil || n < 0 {
		root.setMessage("Set watch interval: invalid number")
		return
	}
	d := root.doc
	d.watchInterval = n
	d.General.WatchInterval = n
	if n > 0 {
		d.watchMode = true
	} else {
		d.watchMode = false
	}
	root.restartWatch(d)
	root.setMessagef("Set watch interval %d", n)
}

func (root *Root) suspend() {
	if err := root.screen.Suspend(); err != nil {
		return
	}
	fmt.Println("suspended ov (use 'fg' to resume)")
	_ = syscall.Kill(0, syscall.SIGSTOP)
	_ = root.screen.Resume()
}

func (root *Root) edit() {
	d := root.doc
	if d.FileName == "" || d.isStdin || d.isExec {
		return
	}
	editor := os.Getenv("OVEDITOR")
	if editor == "" {
		editor = os.Getenv("VISUAL")
	}
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		editor = "vim"
	}
	if err := root.screen.Suspend(); err != nil {
		return
	}
	args := strings.Fields(editor)
	args = append(args, d.FileName)
	c := exec.Command(args[0], args[1:]...)
	c.Stdin = os.Stdin
	c.Stdout = os.Stdout
	c.Stderr = os.Stderr
	_ = c.Run()
	_ = root.screen.Resume()
	_ = d.reloadFile(root.config.SkipExtract)
}

func (root *Root) nextDoc() {
	if root.special != nil {
		return
	}
	if root.cur+1 >= len(root.docs) {
		return
	}
	root.cur++
	root.doc = root.docs[root.cur]
}

func (root *Root) prevDoc() {
	if root.special != nil {
		return
	}
	if root.cur <= 0 {
		return
	}
	root.cur--
	root.doc = root.docs[root.cur]
}

func (root *Root) closeDoc() {
	if root.special != nil {
		return
	}
	if len(root.docs) <= 1 {
		root.setMessage("only this document")
		return
	}
	root.docs = append(root.docs[:root.cur], root.docs[root.cur+1:]...)
	if root.cur >= len(root.docs) {
		root.cur = len(root.docs) - 1
	}
	root.doc = root.docs[root.cur]
}

func (root *Root) closeAllFilter() {
	var nd []*Document
	for _, d := range root.docs {
		if !d.isFilter {
			nd = append(nd, d)
		}
	}
	if len(nd) == 0 {
		return
	}
	cur := root.doc
	root.docs = nd
	root.cur = 0
	for i, d := range nd {
		if d == cur {
			root.cur = i
		}
	}
	root.doc = root.docs[root.cur]
}

func (root *Root) closeFile() {
	d := root.doc
	if d.closed {
		return
	}
	d.closed = true
	d.followMode = false
	root.setMessage("close file")
}

func (root *Root) reload() {
	d := root.doc
	if d.isStdin || d.isExec || d.isFilter || d.isHelp || d.isLog {
		return
	}
	_ = d.reloadFile(root.config.SkipExtract)
	if d.topLN >= d.BufEndNum() {
		d.topLN = d.firstBodyLine()
	}
}

func (root *Root) toggleWatch() {
	d := root.doc
	d.watchMode = !d.watchMode
	if d.watchMode && d.watchInterval <= 0 {
		d.watchInterval = 1
	}
	root.restartWatch(d)
}

func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}
EOF
echo ok"}

