func (root *Root) setConverter(name string) {
	d := root.doc
	switch name {
	case "align":
		d.General.Align = true
		d.General.Converter = "align"
		d.conv = convES
		d.alignInfo = nil
		root.prepareAlign(d)
		root.setMessage("Set align converter")
	case "raw":
		d.General.Align = false
		d.General.Converter = "raw"
		d.conv = convRaw
		root.setMessage("Set raw converter")
	case "es":
		d.General.Align = false
		d.General.Converter = "es"
		d.conv = convES
		root.setMessage("Set es converter")
	default:
		root.setMessage("invalid converter: " + name)
		return
	}
	d.clearCache()
}

