func (root *Root) viewModeCandidates() []string {
	names := []string{"general"}
	var ms []string
	for name := range root.config.Mode {
		ms = append(ms, name)
	}
	sortStrings(ms)
	names = append(names, ms...)
	return names
}

func (root *Root) setViewModeInput(v string) {
	v = strings.TrimSpace(v)
	d := root.doc
	if v == "general" {
		root.reapplyGeneral(d, nil)
		root.setMessage("Set mode general")
		return
	}
	mm, ok := root.config.Mode[v]
	if !ok {
		root.setMessagef("%s mode not found", v)
		return
	}
	root.reapplyGeneral(d, mm)
	root.setMessagef("Set mode %s", v)
}

func (root *Root) reapplyGeneral(d *Document, mm map[string]interface{}) {
	g := root.config.General
	g.set = map[string]bool{}
	d.General = g
	if mm != nil {
		applyGeneralMap(&d.General, mm)
	}
	root.applyGeneral(d)
	if d.topLN < d.firstBodyLine() {
		d.topLN = d.firstBodyLine()
		d.topLX = 0
	}
}

