func (root *Root) suspend() {
	if err := root.screen.Suspend(); err != nil {
		return
	}
	fmt.Println("suspended ov (use 'fg' to resume)")
	_ = syscall.Kill(0, syscall.SIGSTOP)
	_ = root.screen.Resume()
}

func (root *Root) edit() {
	d := root.doc
	if d.FileName == "" || d.isStdin || d.isExec {
		return
	}
	editor := os.Getenv("OVEDITOR")
	if editor == "" {
		editor = os.Getenv("VISUAL")
	}
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		editor = "vim"
	}
	if err := root.screen.Suspend(); err != nil {
		return
	}
	args := strings.Fields(editor)
	args = append(args, d.FileName)
	c := exec.Command(args[0], args[1:]...)
	c.Stdin = os.Stdin
	c.Stdout = os.Stdout
	c.Stderr = os.Stderr
	_ = c.Run()
	_ = root.screen.Resume()
	_ = d.reloadFile(root.config.SkipExtract)
}

func (root *Root) nextDoc() {
	if root.special != nil {
		return
	}
	if root.cur+1 >= len(root.docs) {
		return
	}
	root.cur++
	root.doc = root.docs[root.cur]
}

func (root *Root) prevDoc() {
	if root.special != nil {
		return
	}
	if root.cur <= 0 {
		return
	}
	root.cur--
	root.doc = root.docs[root.cur]
}

func (root *Root) closeDoc() {
	if root.special != nil {
		return
	}
	if len(root.docs) <= 1 {
		root.setMessage("only this document")
		return
	}
	root.docs = append(root.docs[:root.cur], root.docs[root.cur+1:]...)
	if root.cur >= len(root.docs) {
		root.cur = len(root.docs) - 1
	}
	root.doc = root.docs[root.cur]
}

func (root *Root) closeAllFilter() {
	var nd []*Document
	for _, d := range root.docs {
		if !d.isFilter {
			nd = append(nd, d)
		}
	}
	if len(nd) == 0 {
		return
	}
	cur := root.doc
	root.docs = nd
	root.cur = 0
	for i, d := range nd {
		if d == cur {
			root.cur = i
		}
	}
	root.doc = root.docs[root.cur]
}

func (root *Root) closeFile() {
	d := root.doc
	if d.closed {
		return
	}
	d.closed = true
	d.followMode = false
	root.setMessage("close file")
}

func (root *Root) reload() {
	d := root.doc
	if d.isStdin || d.isExec || d.isFilter || d.isHelp || d.isLog {
		return
	}
	_ = d.reloadFile(root.config.SkipExtract)
	if d.topLN >= d.BufEndNum() {
		d.topLN = d.firstBodyLine()
	}
}

func (root *Root) toggleWatch() {
	d := root.doc
	d.watchMode = !d.watchMode
	if d.watchMode && d.watchInterval <= 0 {
		d.watchInterval = 1
	}
	root.restartWatch(d)
}

func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}
