package oviewer

import "strings"

type colRange struct {
	start, end int // content index range [start, end)
}

// columnRanges returns the column ranges of a line.
func (root *Root) columnRanges(d *Document, ln int, lc contents) []colRange {
	if d.General.ColumnWidth {
		return root.widthColumnRanges(d, ln, lc)
	}
	delim := d.General.ColumnDelimiter
	if delim == "" {
		return nil
	}
	if delim == "\\t" {
		delim = "\t"
	}
	str, pos := contentsToString(lc)
	if d.General.TabWidth > 0 && delim == "\t" {
		raw, _ := d.LineString(ln)
		return tabColumns(raw, d, lc)
	}
	var res []colRange
	start := 0
	i := 0
	quoted := delim == ","
	for i <= len(str) {
		if i == len(str) {
			res = append(res, colRange{pos[start], pos[i]})
			break
		}
		if quoted && i == start && str[i] == '"' {
			// quoted field
			j := i + 1
			for j < len(str) {
				if str[j] == '"' {
					if j+1 < len(str) && str[j+1] == '"' {
						j += 2
						continue
					}
					break
				}
				j++
			}
			if j < len(str) && (j+1 == len(str) || strings.HasPrefix(str[j+1:], delim)) {
				i = j + 1
				continue
			}
		}
		if strings.HasPrefix(str[i:], delim) {
			res = append(res, colRange{pos[start], pos[i]})
			i += len(delim)
			start = i
			continue
		}
		i++
	}
	// skip leading empty column when line begins with delimiter
	if len(res) > 1 && res[0].start == res[0].end && strings.HasPrefix(str, delim) {
		res = res[1:]
	}
	return res
}

func tabColumns(raw string, d *Document, lc contents) []colRange {
	// columns separated by tab characters: compute from raw string
	var res []colRange
	x := 0
	idx := 0
	start := 0
	tw := d.General.TabWidth
	for _, r := range raw {
		if r == '\t' {
			res = append(res, colRange{start, idx})
			sp := tw - (x % tw)
			idx += sp
			x += sp
			start = idx
			continue
		}
		w := runeWidth(r)
		if w == 2 {
			idx += 2
		} else {
			idx++
		}
		x += w
	}
	res = append(res, colRange{start, idx})
	if idx > len(lc) {
		for i := range res {
			if res[i].end > len(lc) {
				res[i].end = len(lc)
			}
			if res[i].start > len(lc) {
				res[i].start = len(lc)
			}
		}
	}
	return res
}

// widthColumnRanges detects columns separated by spaces.
func (root *Root) widthColumnRanges(d *Document, ln int, lc contents) []colRange {
	if d.columnWidths == nil {
		root.detectColumnWidths(d)
	}
	var res []colRange
	start := 0
	for _, p := range d.columnWidths {
		if p > len(lc) {
			break
		}
		res = append(res, colRange{start, p})
		start = p + 1
	}
	if start <= len(lc) {
		res = append(res, colRange{start, len(lc)})
	}
	return res
}

func (root *Root) detectColumnWidths(d *Document) {
	n := d.BufEndNum()
	limit := 1000
	if n > limit {
		n = limit
	}
	maxLen := 0
	var lines []contents
	for i := 0; i < n; i++ {
		lc := root.contentsOf(d, i)
		lines = append(lines, lc)
		if len(lc) > maxLen {
			maxLen = len(lc)
		}
	}
	space := make([]int, maxLen+1)
	for _, lc := range lines {
		for i := 0; i < maxLen; i++ {
			if i >= len(lc) || lc[i].mainc == ' ' {
				space[i]++
			}
		}
	}
	var seps []int
	total := len(lines)
	inText := false
	for i := 0; i < maxLen; i++ {
		if space[i] == total {
			if inText {
				seps = append(seps, i)
			}
			inText = false
		} else {
			inText = true
		}
	}
	d.columnWidths = seps
	if d.columnWidths == nil {
		d.columnWidths = []int{}
	}
}

func (root *Root) maxColumns() int {
	d := root.doc
	ly := root.computeLayout(d)
	max := 0
	for _, r := range ly.headerRows {
		n := len(root.columnRanges(d, r.ln, root.contentsOf(d, r.ln)))
		if n > max {
			max = n
		}
	}
	for _, r := range ly.bodyRows {
		if r.ln < 0 {
			continue
		}
		n := len(root.columnRanges(d, r.ln, root.contentsOf(d, r.ln)))
		if n > max {
			max = n
		}
	}
	return max
}

func (root *Root) columnRight() {
	d := root.doc
	max := root.maxColumns()
	if max == 0 {
		return
	}
	if d.columnCursor+1 >= max {
		if root.config.DisableColumnCycle {
			return
		}
		d.columnCursor = 0
		if !d.General.WrapMode {
			d.x = 0
		}
		return
	}
	d.columnCursor++
	root.scrollToColumn()
}

func (root *Root) columnLeft() {
	d := root.doc
	max := root.maxColumns()
	if max == 0 {
		return
	}
	if d.columnCursor <= 0 {
		if root.config.DisableColumnCycle {
			return
		}
		d.columnCursor = max - 1
		root.scrollToColumn()
		return
	}
	d.columnCursor--
	root.scrollToColumn()
}

func (root *Root) scrollToColumn() {
	d := root.doc
	if d.General.WrapMode {
		return
	}
	ly := root.computeLayout(d)
	w := ly.contentW
	// find column range from first visible line having it
	for _, r := range append(ly.headerRows, ly.bodyRows...) {
		if r.ln < 0 {
			continue
		}
		lc := root.contentsOf(d, r.ln)
		cols := root.columnRanges(d, r.ln, lc)
		if d.columnCursor >= len(cols) {
			continue
		}
		c := cols[d.columnCursor]
		vh := root.verticalHeaderWidth(d, r.ln, lc)
		if c.start < vh {
			return
		}
		if c.start-vh < d.x {
			d.x = c.start - vh
			if d.x < 0 {
				d.x = 0
			}
		} else if c.end > d.x+w {
			d.x = c.end - w + 1
			if c.start-vh < d.x {
				d.x = c.start - vh
			}
		}
		return
	}
}

// ---- align ----

type alignInfo struct {
	widths []int
}

func (root *Root) prepareAlign(d *Document) {
	d.alignInfo = &alignInfo{}
}

func (root *Root) alignContents(d *Document, n int, lc contents) contents {
	return lc
}

func (root *Root) shrinkColumn() {
	root.setMessage("shrink column")
}

func (root *Root) rightAlignColumn() {
	root.setMessage("right align column")
}
