cat > /workspace/oviewer/misc.go <<'EOF'
package oviewer

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
	"time"

	"github.com/gdamore/tcell/v2"
)

const (
	sidebarNone = iota
	sidebarHelp
	sidebarMarks
	sidebarDocs
)

func stripEscapes(s string) string {
	if strings.IndexByte(s, 0x1b) < 0 {
		return s
	}
	lc := parseLine(s, 8, convES, true)
	str, _ := contentsToString(lc)
	return str
}

// ---- marks ----

func (d *Document) isMarked(n int) bool {
	for _, m := range d.marks {
		if m == n {
			return true
		}
	}
	return false
}

func (root *Root) displayLineNum(d *Document, ln int) int {
	return ln - d.firstBodyLine() + 1
}

func (root *Root) addMark() {
	d := root.doc
	ln := root.currentLine()
	if !d.isMarked(ln) {
		d.marks = append(d.marks, ln)
	}
	for i, m := range d.marks {
		if m == ln {
			d.markIdx = i
		}
	}
	root.setMessagef("Marked to line %d", root.displayLineNum(d, ln))
}

func (root *Root) removeMark() {
	d := root.doc
	ln := root.currentLine()
	for i, m := range d.marks {
		if m == ln {
			d.marks = append(d.marks[:i], d.marks[i+1:]...)
			if d.markIdx >= len(d.marks) {
				d.markIdx = len(d.marks) - 1
			}
			if d.markIdx < 0 {
				d.markIdx = 0
			}
			root.setMessagef("Remove the mark at line %d", root.displayLineNum(d, ln))
			return
		}
	}
	root.setMessagef("Not marked line %d", root.displayLineNum(d, ln))
}

func (root *Root) nextMark() {
	d := root.doc
	if len(d.marks) == 0 {
		return
	}
	d.markIdx++
	if d.markIdx >= len(d.marks) {
		d.markIdx = 0
	}
	root.moveToMark(d.markIdx)
}

func (root *Root) prevMark() {
	d := root.doc
	if len(d.marks) == 0 {
		return
	}
	d.markIdx--
	if d.markIdx < 0 {
		d.markIdx = len(d.marks) - 1
	}
	root.moveToMark(d.markIdx)
}

func (root *Root) moveToMark(i int) {
	d := root.doc
	if i < 0 || i >= len(d.marks) {
		return
	}
	ln := d.marks[i]
	root.moveLine(ln)
	root.setMessagef("Moved to line %d", root.displayLineNum(d, ln))
}

func (root *Root) markNumberInput(v string) {
	root.sidebar = sidebarNone
	d := root.doc
	n, err := strconv.Atoi(strings.TrimSpace(v))
	if err != nil || n < 0 || n >= len(d.marks) {
		root.setMessage("Sidebar hidden")
		return
	}
	d.markIdx = n
	root.moveToMark(n)
}

func (root *Root) markByPattern(v string) {
	d := root.doc
	s := root.newSearcher(v)
	if s == nil {
		return
	}
	count := 0
	total := d.BufEndNum()
	for n := d.firstBodyLine(); n < total; n++ {
		str, ok := root.lineSearchString(d, n)
		if !ok || !s.Match(str) {
			continue
		}
		if !d.isMarked(n) {
			d.marks = append(d.marks, n)
			count++
		}
	}
	sortInts(d.marks)
	root.setMessagef("Added %d marks", count)
}

func sortInts(a []int) {
	for i := 1; i < len(a); i++ {
		for j := i; j > 0 && a[j] < a[j-1]; j-- {
			a[j], a[j-1] = a[j-1], a[j]
		}
	}
}

// ---- sections ----

func (root *Root) sectionLines() []int {
	d := root.doc
	var res []int
	if d.sectionDelimReg == nil {
		return res
	}
	total := d.BufEndNum()
	_, he := d.headerRange()
	for n := he; n < total; n++ {
		s, _ := d.LineString(n)
		if d.sectionDelimReg.MatchString(stripEscapes(s)) {
			res = append(res, n+d.General.SectionStartPosition)
		}
	}
	return res
}

func (root *Root) nextSection() {
	d := root.doc
	if d.sectionDelimReg == nil {
		root.moveDownRows(root.pageRows())
		return
	}
	cur := d.topLN
	for _, s := range root.sectionLines() {
		if s > cur {
			root.setPos(pos{s, 0})
			return
		}
	}
	root.moveDownRows(root.pageRows())
}

func (root *Root) prevSection() {
	d := root.doc
	if d.sectionDelimReg == nil {
		root.moveUpRows(root.pageRows())
		return
	}
	cur := d.topLN
	secs := root.sectionLines()
	for i := len(secs) - 1; i >= 0; i-- {
		if secs[i] < cur {
			root.setPos(pos{secs[i], 0})
			return
		}
	}
	root.moveTop()
}

func (root *Root) lastSection() {
	d := root.doc
	if d.sectionDelimReg == nil {
		root.moveBottom()
		return
	}
	secs := root.sectionLines()
	if len(secs) == 0 {
		root.moveBottom()
		return
	}
	root.setPos(pos{secs[len(secs)-1], 0})
}

// ---- jump target ----

func (root *Root) jumpTargetOffset(d *Document, n int) int {
	spec := d.jumpTargetSpec
	if spec == "" || spec == "section" {
		return 0
	}
	h := root.computeLayoutLite(d)
	if strings.HasSuffix(spec, "%") {
		f, err := strconv.ParseFloat(strings.TrimSuffix(spec, "%"), 64)
		if err != nil {
			return 0
		}
		return int(float64(h) * f / 100)
	}
	if strings.HasPrefix(spec, ".") {
		f, err := strconv.ParseFloat("0"+spec, 64)
		if err != nil {
			return 0
		}
		return int(float64(h) * f)
	}
	v, err := strconv.Atoi(spec)
	if err != nil {
		return 0
	}
	if v < 0 {
		v = h + v
	}
	if v < 0 {
		v = 0
	}
	if v >= h {
		v = h - 1
	}
	return v
}

func (root *Root) jumpTargetRow(d *Document, ly *layout) int {
	if d.jumpTargetSpec == "" || d.jumpTargetSpec == "section" {
		return -1
	}
	return root.jumpTargetOffset(d, 0)
}

// ---- help / log ----

func (root *Root) toggleHelp() {
	if root.special != nil && root.special.isHelp {
		root.closeSpecial()
		return
	}
	if root.helpDoc == nil {
		root.helpDoc = root.newHelpDoc()
	}
	if root.special == nil {
		root.prevDoc = root.doc
	}
	root.special = root.helpDoc
	root.doc = root.helpDoc
}

func (root *Root) toggleLog() {
	if root.special != nil && root.special.isLog {
		root.closeSpecial()
		return
	}
	if root.logDoc == nil {
		d := newDocument()
		d.isLog = true
		d.FileName = "Log"
		d.General = DefaultGeneral()
		d.cache = map[int]contents{}
		root.logDoc = d
	}
	root.logDoc.setLines(append([]string{}, root.logs...))
	if root.special == nil {
		root.prevDoc = root.doc
	}
	root.special = root.logDoc
	root.doc = root.logDoc
}

func (root *Root) closeSpecial() {
	root.special = nil
	if root.prevDoc != nil {
		root.doc = root.prevDoc
	} else {
		root.doc = root.docs[root.cur]
	}
}

func (root *Root) newHelpDoc() *Document {
	d := newDocument()
	d.isHelp = true
	d.FileName = "Help"
	d.Caption = "Help"
	g := DefaultGeneral()
	g.Header = 2
	g.WrapMode = false
	g.Style.Header = OVStyle{Foreground: "gold", Background: "darkblue", Bold: true}
	g.Style.SectionLine = OVStyle{Background: "slateblue", Bold: true}
	g.SectionDelimiter = "^\t"
	d.General = g
	d.setSectionDelimiter(g.SectionDelimiter)
	text := "                        \x1b[4mov help\x1b[24m\n" + KeyBindString(root.keyBind)
	d.loadBytes([]byte(text))
	d.topLN = d.firstBodyLine()
	return d
}

// ---- sidebar ----

func (root *Root) toggleSidebar(kind int) {
	names := map[int]string{sidebarHelp: "Help", sidebarMarks: "Marks", sidebarDocs: "Files"}
	if root.sidebar == kind {
		root.sidebar = sidebarNone
		root.setMessage("Sidebar hidden")
		return
	}
	root.sidebar = kind
	root.sidebarY = 0
	root.sidebarX = 0
	root.setMessagef("Sidebar %s visible", names[kind])
}

func (root *Root) drawSidebar(ly *layout) {
	w := ly.sidebarW - 1
	lines := root.sidebarLines(w)
	h := ly.statusY
	for y := 0; y < h; y++ {
		idx := y
		if y > 0 {
			idx = y + root.sidebarY
		}
		if idx < len(lines) {
			sl := lines[idx]
			x := 0
			for _, c := range sl.text {
				if x >= w {
					break
				}
				root.screen.SetContent(x, y, c, nil, sl.style)
				x += runeWidth(c)
			}
		}
		root.screen.SetContent(w, y, ' ', nil, tcell.StyleDefault.Background(tcell.ColorGray))
	}
}

type sideLine struct {
	text  string
	style tcell.Style
}

func (root *Root) sidebarLines(w int) []sideLine {
	var res []sideLine
	bold := tcell.StyleDefault.Bold(true)
	switch root.sidebar {
	case sidebarHelp:
		res = append(res, sideLine{"   Help", tcell.StyleDefault})
		res[0] = sideLine{"   Help", tcell.StyleDefault}
		for _, g := range actionGroups {
			for _, a := range g.actions {
				keys := strings.Join(root.keyBind[a.name], ", ")
				res = append(res, sideLine{"[" + keys + "]", tcell.StyleDefault})
				res = append(res, sideLine{"  " + a.desc, tcell.StyleDefault})
			}
		}
	case sidebarMarks:
		res = append(res, sideLine{"   Marks", tcell.StyleDefault})
		d := root.doc
		for i, m := range d.marks {
			s, _ := d.LineString(m)
			s = stripEscapes(s)
			res = append(res, sideLine{fmt.Sprintf("%2d %d %s", i, m, s), tcell.StyleDefault})
		}
	case sidebarDocs:
		res = append(res, sideLine{"   Files", tcell.StyleDefault})
		for i, d := range root.docs {
			res = append(res, sideLine{fmt.Sprintf("%2d %s", i, d.FileName), tcell.StyleDefault})
		}
	}
	_ = bold
	return res
}

// ---- timers / updates ----

func (root *Root) startTimers() {
	go func() {
		t := time.NewTicker(250 * time.Millisecond)
		for range t.C {
			if root.quit {
				t.Stop()
				return
			}
			ev := &eventTimer{id: 0}
			ev.SetEventNow()
			_ = root.screen.PostEvent(ev)
		}
	}()
	for _, d := range root.docs {
		if d.watchMode {
			root.restartWatch(d)
		}
	}
}

func (root *Root) stopTimers() {
	for _, t := range root.watchTimers {
		t.Stop()
	}
}

func (root *Root) restartWatch(d *Document) {
	if root.watchTimers == nil {
		root.watchTimers = map[*Document]*time.Ticker{}
	}
	if t, ok := root.watchTimers[d]; ok {
		t.Stop()
		delete(root.watchTimers, d)
	}
	if !d.watchMode || d.watchInterval <= 0 || root.screen == nil {
		return
	}
	t := time.NewTicker(time.Duration(d.watchInterval) * time.Second)
	root.watchTimers[d] = t
	doc := d
	go func() {
		for range t.C {
			if root.quit {
				return
			}
			ev := &eventWatch{doc: doc}
			ev.SetEventNow()
			_ = root.screen.PostEvent(ev)
		}
	}()
}

type eventWatch struct {
	tcell.EventTime
	doc *Document
}

func (root *Root) onTimer(id int) {
	// follow mode polling
	for _, d := range root.docs {
		if d.closed {
			continue
		}
		if d.followMode || d.followAll || d.followSection || d.followName {
			if d.followFile() {
				root.afterAppend(d)
			}
		}
	}
	root.afterUpdateFollow()
}

func (root *Root) afterAppend(d *Document) {
	if d.followAll {
		// switch to most recently updated
		for i, dd := range root.docs {
			if dd == d && root.special == nil {
				root.cur = i
				root.doc = d
			}
		}
	}
}

func (root *Root) afterUpdateFollow() {
	for _, d := range root.docs {
		if d.followMode || d.followAll || d.followName {
			root.withDoc(d, func() { root.moveBottomFollow() })
		} else if d.followSection {
			root.withDoc(d, func() { root.lastSection() })
		}
	}
}

func (root *Root) onUpdate() {
	root.afterUpdateFollow()
}

func (root *Root) onWatch(d *Document) {
	if d.isStdin || d.isExec {
		return
	}
	_ = d.reloadFile(root.config.SkipExtract)
	root.withDoc(d, func() { root.moveBottomFollow() })
}

// ---- output ----

// screenLines returns the current screen as text lines for exit output.
func (root *Root) screenLines() []string {
	d := root.doc
	ly := root.computeLayout(d)
	var out []string
	add := func(r rowSpec) {
		if r.ln < 0 {
			return
		}
		lc := root.contentsOf(d, r.ln)
		var cells contents
		if d.General.WrapMode {
			end := r.end
			if end > len(lc) {
				end = len(lc)
			}
			if r.lx < end {
				cells = lc[r.lx:end]
			}
		} else {
			if d.x < len(lc) {
				end := d.x + ly.contentW
				if end > len(lc) {
					end = len(lc)
				}
				cells = lc[d.x:end]
			}
		}
		prefix := ""
		if ly.numW > 0 {
			prefix = fmt.Sprintf("%*d ", ly.numW-1, root.displayLineNum(d, r.ln))
		}
		out = append(out, prefix+contentsToANSI(cells))
	}
	for _, r := range ly.headerRows {
		add(r)
	}
	for _, r := range ly.sectionRows {
		add(r)
	}
	for _, r := range ly.bodyRows {
		add(r)
	}
	// extend to screen height
	if !d.General.WrapMode || true {
		last := -1
		lastEnd := 0
		if len(ly.bodyRows) > 0 {
			lr := ly.bodyRows[len(ly.bodyRows)-1]
			last = lr.ln
			lastEnd = lr.end
		}
		if last >= 0 && len(out) < root.height {
			ln := last
			lx := lastEnd
			lc := root.contentsOf(d, ln)
			if !d.General.WrapMode || lx >= len(lc) {
				ln++
				lx = 0
			}
			for len(out) < root.height && ln < d.BufEndNum() {
				lc = root.contentsOf(d, ln)
				end := len(lc)
				if d.General.WrapMode {
					end = nextBreak(lc, lx, ly.contentW)
				}
				r := rowSpec{ln: ln, lx: lx, end: end}
				add(r)
				if !d.General.WrapMode || end >= len(lc) {
					ln++
					lx = 0
				} else {
					lx = end
				}
			}
		}
	}
	return out
}

func contentsToANSI(lc contents) string {
	var b bytes.Buffer
	cur := tcell.StyleDefault
	for _, c := range lc {
		if c.width == 0 && c.mainc == 0 {
			continue
		}
		if c.style != cur {
			b.WriteString(styleToSGR(c.style))
			cur = c.style
		}
		b.WriteRune(c.mainc)
		for _, cr := range c.combc {
			b.WriteRune(cr)
		}
	}
	if cur != tcell.StyleDefault {
		b.WriteString("\x1b[0m")
	}
	s := b.String()
	return strings.TrimRight(s, " ")
}

func styleToSGR(s tcell.Style) string {
	if s == tcell.StyleDefault {
		return "\x1b[0m"
	}
	fg, bg, attr := s.Decompose()
	var parts []string
	if attr&tcell.AttrBold != 0 {
		parts = append(parts, "1")
	}
	if attr&tcell.AttrDim != 0 {
		parts = append(parts, "2")
	}
	if attr&tcell.AttrItalic != 0 {
		parts = append(parts, "3")
	}
	if s.GetUnderlineStyle() != tcell.UnderlineStyleNone {
		parts = append(parts, "4")
	}
	if attr&tcell.AttrBlink != 0 {
		parts = append(parts, "5")
	}
	if attr&tcell.AttrReverse != 0 {
		parts = append(parts, "7")
	}
	if attr&tcell.AttrStrikeThrough != 0 {
		parts = append(parts, "9")
	}
	if fg != tcell.ColorDefault {
		parts = append(parts, colorSGR(fg, 30))
	}
	if bg != tcell.ColorDefault {
		parts = append(parts, colorSGR(bg, 40))
	}
	res := "\x1b[0m"
	for _, p := range parts {
		res += "\x1b[" + p + "m"
	}
	return res
}

func colorSGR(c tcell.Color, base int) string {
	if c.IsRGB() {
		r, g, b := c.RGB()
		return fmt.Sprintf("%d;2;%d;%d;%d", base+8, r, g, b)
	}
	n := int(c - tcell.ColorValid)
	if n < 8 {
		return strconv.Itoa(base + n)
	}
	return fmt.Sprintf("%d;5;%d", base+8, n)
}

func (root *Root) fitsOneScreen() bool {
	d := root.doc
	if !d.BufEOF() {
		return false
	}
	h := root.height - 1
	rows := 0
	total := d.BufEndNum()
	for n := 0; n < total; n++ {
		rows += root.rowsOfLine(d, n)
		if rows > h {
			return false
		}
	}
	return true
}

func (root *Root) writeAll(w io.Writer) {
	d := root.doc
	total := d.BufEndNum()
	for n := 0; n < total; n++ {
		s, _ := d.LineString(n)
		fmt.Fprintln(w, s)
	}
}

func (root *Root) saveBuffer(name string) {
	name = strings.TrimSpace(name)
	if name == "" {
		return
	}
	d := root.doc
	f, err := os.Create(name)
	if err != nil {
		root.setMessage(err.Error())
		return
	}
	defer f.Close()
	total := d.BufEndNum()
	for n := 0; n < total; n++ {
		s, _ := d.LineString(n)
		fmt.Fprintln(f, s)
	}
	root.setMessagef("Saved %s", name)
}
EOF
