package oviewer

import (
	"bytes"
	"compress/bzip2"
	"compress/gzip"
	"io"
)

// decompress tries to decompress data; returns false if not compressed.
func decompress(data []byte) ([]byte, bool) {
	switch {
	case bytes.HasPrefix(data, []byte{0x1f, 0x8b}):
		r, err := gzip.NewReader(bytes.NewReader(data))
		if err != nil {
			return nil, false
		}
		out, err := io.ReadAll(r)
		if err != nil && len(out) == 0 {
			return nil, false
		}
		return out, true
	case bytes.HasPrefix(data, []byte("BZh")):
		out, err := io.ReadAll(bzip2.NewReader(bytes.NewReader(data)))
		if err != nil && len(out) == 0 {
			return nil, false
		}
		return out, true
	case bytes.HasPrefix(data, []byte{0x28, 0xb5, 0x2f, 0xfd}):
		out, err := zstdDecode(data)
		if err != nil && len(out) == 0 {
			return nil, false
		}
		return out, true
	case bytes.HasPrefix(data, []byte{0x04, 0x22, 0x4d, 0x18}):
		out, err := lz4Decode(data)
		if err != nil && len(out) == 0 {
			return nil, false
		}
		return out, true
	case bytes.HasPrefix(data, []byte{0xfd, '7', 'z', 'X', 'Z', 0x00}):
		out, err := xzDecode(data)
		if err != nil && len(out) == 0 {
			return nil, false
		}
		return out, true
	}
	return nil, false
}
