			}
		}
	case sidebarMarks:
		res = append(res, title("Marks"))
		d := root.doc
		cur := root.currentLine()
		for i, m := range d.marks {
			s, _ := d.LineString(m)
			s = cutTab(stripEscapes(s))
			idxStyle := tcell.StyleDefault.Italic(true)
			txtStyle := tcell.StyleDefault
			if m == cur {
				idxStyle = idxStyle.Bold(true).Reverse(true)
				txtStyle = txtStyle.Bold(true).Reverse(true)
			}
			res = append(res, sideLine{segs: []sideSeg{
				{fmt.Sprintf("%2d ", i), idxStyle},
				{fmt.Sprintf("%d %s", m, s), txtStyle},
			}})
		}
	case sidebarDocs:
		res = append(res, title("Files"))
		for i, d := range root.docs {
			idxStyle := tcell.StyleDefault.Italic(true)
			txtStyle := tcell.StyleDefault
			if i == root.cur {
				idxStyle = idxStyle.Bold(true).Reverse(true)
				txtStyle = txtStyle.Bold(true).Reverse(true)
			}
