package oviewer

import (
	"encoding/binary"
	"errors"
)

var errLZ4 = errors.New("lz4: corrupt input")

// lz4Decode decodes LZ4 frame format data (possibly concatenated frames).
func lz4Decode(data []byte) ([]byte, error) {
	var out []byte
	p := 0
	for p+4 <= len(data) {
		magic := binary.LittleEndian.Uint32(data[p:])
		switch {
		case magic == 0x184D2204:
			n, o, err := lz4Frame(data[p:], out)
			out = o
			if err != nil {
				return out, err
			}
			p += n
		case magic&0xFFFFFFF0 == 0x184D2A50:
			if p+8 > len(data) {
				return out, errLZ4
			}
			sz := int(binary.LittleEndian.Uint32(data[p+4:]))
			p += 8 + sz
		case magic == 0x184C2102:
			// legacy frame
			p += 4
			for p+4 <= len(data) {
				bs := int(binary.LittleEndian.Uint32(data[p:]))
				if bs == 0x184C2102 || bs == 0x184D2204 {
					break
				}
				p += 4
				if p+bs > len(data) {
					return out, errLZ4
				}
				var err error
				out, err = lz4Block(data[p:p+bs], out, len(out))
				if err != nil {
					return out, err
				}
				p += bs
			}
		default:
			if len(out) == 0 {
				return nil, errLZ4
			}
			return out, nil
		}
	}
	return out, nil
}

func lz4Frame(data []byte, out []byte) (int, []byte, error) {
	if len(data) < 7 {
		return 0, out, errLZ4
	}
	flg := data[4]
	p := 6
	blockChecksum := flg&0x10 != 0
	contentSize := flg&0x08 != 0
	contentChecksum := flg&0x04 != 0
	dictID := flg&0x01 != 0
	indep := flg&0x20 != 0
	if contentSize {
		p += 8
	}
	if dictID {
		p += 4
	}
	p++ // header checksum
	frameStart := len(out)
	for {
		if p+4 > len(data) {
			return p, out, errLZ4
		}
		bs := binary.LittleEndian.Uint32(data[p:])
		p += 4
		if bs == 0 {
			break
		}
		uncompressed := bs&0x80000000 != 0
		size := int(bs & 0x7FFFFFFF)
		if p+size > len(data) {
			return p, out, errLZ4
		}
		blk := data[p : p+size]
		if uncompressed {
			out = append(out, blk...)
		} else {
			base := frameStart
			if indep {
				base = len(out)
			}
			var err error
			out, err = lz4Block(blk, out, base)
			if err != nil {
				return p, out, err
			}
		}
		p += size
		if blockChecksum {
			p += 4
		}
	}
	if contentChecksum {
		p += 4
	}
	return p, out, nil
}

// lz4Block decodes a raw lz4 block appending to out. base is the lowest
// position a match may reference.
func lz4Block(src []byte, out []byte, base int) ([]byte, error) {
	ip := 0
	n := len(src)
	for ip < n {
		token := src[ip]
		ip++
		litLen := int(token >> 4)
		if litLen == 15 {
			for ip < n {
				b := src[ip]
				ip++
				litLen += int(b)
				if b != 255 {
					break
				}
			}
		}
		if ip+litLen > n {
			return out, errLZ4
		}
		out = append(out, src[ip:ip+litLen]...)
		ip += litLen
		if ip >= n {
			break
		}
		if ip+2 > n {
			return out, errLZ4
		}
		offset := int(src[ip]) | int(src[ip+1])<<8
		ip += 2
		matchLen := int(token & 15)
		if matchLen == 15 {
			for ip < n {
				b := src[ip]
				ip++
				matchLen += int(b)
				if b != 255 {
					break
				}
			}
		}
		matchLen += 4
		start := len(out) - offset
		if offset == 0 || start < 0 {
			return out, errLZ4
		}
		_ = base
		for i := 0; i < matchLen; i++ {
			out = append(out, out[start+i])
		}
	}
	return out, nil
}
