package oviewer

import (
	"bytes"
	"errors"
)

var errXZ = errors.New("xz: corrupt input")

var xzMagic = []byte{0xfd, '7', 'z', 'X', 'Z', 0x00}

var xzCheckSizes = [16]int{0, 4, 4, 4, 8, 8, 8, 16, 16, 16, 32, 32, 32, 64, 64, 64}

func readVarint(b []byte, p int) (uint64, int, error) {
	var v uint64
	for i := 0; i < 9; i++ {
		if p >= len(b) {
			return 0, p, errXZ
		}
		c := b[p]
		p++
		v |= uint64(c&0x7f) << (7 * uint(i))
		if c&0x80 == 0 {
			return v, p, nil
		}
	}
	return 0, p, errXZ
}

// xzDecode decodes .xz data.
func xzDecode(data []byte) ([]byte, error) {
	var out []byte
	p := 0
	for p < len(data) {
		// skip stream padding
		for p < len(data) && data[p] == 0 {
			p++
		}
		if p >= len(data) {
			break
		}
		if !bytes.HasPrefix(data[p:], xzMagic) || p+12 > len(data) {
			if len(out) > 0 {
				return out, nil
			}
			return nil, errXZ
		}
		check := int(data[p+7] & 0x0f)
		checkSize := xzCheckSizes[check]
		p += 12
		// blocks
		for {
			if p >= len(data) {
				return out, errXZ
			}
			if data[p] == 0 {
				// index
				break
			}
			hsize := (int(data[p]) + 1) * 4
			if p+hsize > len(data) {
				return out, errXZ
			}
			hdr := data[p : p+hsize]
			flags := hdr[1]
			q := 2
			var err error
			if flags&0x40 != 0 {
				_, q, err = readVarint(hdr, q)
				if err != nil {
					return out, err
				}
			}
			if flags&0x80 != 0 {
				_, q, err = readVarint(hdr, q)
				if err != nil {
					return out, err
				}
			}
			nf := int(flags&3) + 1
			type filter struct {
				id    uint64
				props []byte
			}
			var filters []filter
			for i := 0; i < nf; i++ {
				var id, psz uint64
				id, q, err = readVarint(hdr, q)
				if err != nil {
					return out, err
				}
				psz, q, err = readVarint(hdr, q)
				if err != nil {
					return out, err
				}
				if q+int(psz) > len(hdr) {
					return out, errXZ
				}
				filters = append(filters, filter{id, hdr[q : q+int(psz)]})
				q += int(psz)
			}
