		var err error
		nrec, p, err = readVarint(data, p)
		if err != nil {
			return out, err
		}
		for i := uint64(0); i < nrec; i++ {
			_, p, err = readVarint(data, p)
			if err != nil {
				return out, err
			}
			_, p, err = readVarint(data, p)
			if err != nil {
				return out, err
			}
		}
		for p%4 != 0 {
			p++
		}
		p += 4  // crc
		p += 12 // footer
	}
	return out, nil
}

// ---- LZMA2 ----

type lzmaDecoder struct {
	lc, lp, pb uint
	state      int
	rep        [4]uint32
	isMatch    [12 << 4]uint16
	isRep      [12]uint16
	isRepG0    [12]uint16
	isRepG1    [12]uint16
	isRepG2    [12]uint16
	isRep0Long [12 << 4]uint16
	posSlot    [4][64]uint16
	posDec     [115]uint16
	align      [16]uint16
	lenDec     lzmaLenDecoder
	repLenDec  lzmaLenDecoder
	literal    []uint16
	// range coder
	rng  uint32
	code uint32
	in   []byte
	ip   int
	// dictionary/output
	out       []byte
	dictStart int
}

type lzmaLenDecoder struct {
	choice  uint16
	choice2 uint16
	low     [16][8]uint16
	mid     [16][8]uint16
	high    [256]uint16
}

func initProbs(p []uint16) {
	for i := range p {
		p[i] = 1024
	}
}

func (l *lzmaLenDecoder) reset() {
	l.choice = 1024
	l.choice2 = 1024
	for i := range l.low {
		initProbs(l.low[i][:])
		initProbs(l.mid[i][:])
	}
	initProbs(l.high[:])
}

func (d *lzmaDecoder) resetState() {
	d.state = 0
	d.rep = [4]uint32{}
	initProbs(d.isMatch[:])
	initProbs(d.isRep[:])
	initProbs(d.isRepG0[:])
	initProbs(d.isRepG1[:])
	initProbs(d.isRepG2[:])
	initProbs(d.isRep0Long[:])
	for i := range d.posSlot {
		initProbs(d.posSlot[i][:])
	}
	initProbs(d.posDec[:])
	initProbs(d.align[:])
	d.lenDec.reset()
	d.repLenDec.reset()
	n := 0x300 << (d.lc + d.lp)
	if cap(d.literal) >= n {
		d.literal = d.literal[:n]
	} else {
		d.literal = make([]uint16, n)
	}
	initProbs(d.literal)
}

func (d *lzmaDecoder) rcInit() error {
	if d.ip+5 > len(d.in) {
		return errXZ
	}
	d.ip++ // first byte is 0
	d.code = uint32(d.in[d.ip])<<24 | uint32(d.in[d.ip+1])<<16 | uint32(d.in[d.ip+2])<<8 | uint32(d.in[d.ip+3])
	d.ip += 4
	d.rng = 0xFFFFFFFF
	return nil
}

func (d *lzmaDecoder) normalize() {
	if d.rng < 1<<24 {
		d.rng <<= 8
		var b byte
		if d.ip < len(d.in) {
			b = d.in[d.ip]
		}
		d.ip++
		d.code = d.code<<8 | uint32(b)
	}
}

func (d *lzmaDecoder) bit(p *uint16) uint32 {
	d.normalize()
	bound := (d.rng >> 11) * uint32(*p)
	if d.code < bound {
		d.rng = bound
		*p += (2048 - *p) >> 5
		return 0
	}
	d.rng -= bound
	d.code -= bound
	*p -= *p >> 5
	return 1
}

func (d *lzmaDecoder) direct(n uint) uint32 {
	var res uint32
	for i := uint(0); i < n; i++ {
		d.normalize()
		d.rng >>= 1
		var b uint32
		if d.code >= d.rng {
			d.code -= d.rng
			b = 1
		}
		res = res<<1 | b
	}
	return res
}

func (d *lzmaDecoder) bittree(probs []uint16, bits uint) uint32 {
	m := uint32(1)
	for i := uint(0); i < bits; i++ {
		m = m<<1 | d.bit(&probs[m])
	}
	return m - (1 << bits)
}

func (d *lzmaDecoder) revBittree(probs []uint16, base int, bits uint) uint32 {
	m := 1
	var res uint32
	for i := uint(0); i < bits; i++ {
		b := d.bit(&probs[base+m])
		m = m<<1 | int(b)
		res |= b << i
	}
	return res
}

func (d *lzmaDecoder) decodeLen(l *lzmaLenDecoder, posState int) uint32 {
	if d.bit(&l.choice) == 0 {
		return d.bittree(l.low[posState][:], 3)
	}
	if d.bit(&l.choice2) == 0 {
		return 8 + d.bittree(l.mid[posState][:], 3)
	}
	return 16 + d.bittree(l.high[:], 8)
}

func (d *lzmaDecoder) getByte(dist uint32) byte {
	i := len(d.out) - int(dist) - 1
	if i < d.dictStart || i < 0 {
		return 0
	}
	return d.out[i]
}

// decodeChunk decodes until unpacked bytes are produced.
func (d *lzmaDecoder) decodeChunk(unpacked int) error {
	target := len(d.out) + unpacked
	pbMask := (1 << d.pb) - 1
	lpMask := (1 << d.lp) - 1
	for len(d.out) < target {
		pos := len(d.out) - d.dictStart
		posState := pos & pbMask
		if d.bit(&d.isMatch[d.state<<4+posState]) == 0 {
			// literal
			prev := byte(0)
			if len(d.out) > d.dictStart {
				prev = d.out[len(d.out)-1]
			}
			idx := 0x300 * (((pos & lpMask) << d.lc) + int(prev)>>(8-d.lc))
			probs := d.literal[idx : idx+0x300]
			sym := uint32(1)
			if d.state >= 7 {
				match := uint32(d.getByte(d.rep[0]))
				for sym < 0x100 {
					mb := (match >> 7) & 1
					match <<= 1
					b := d.bit(&probs[((1+mb)<<8)+sym])
					sym = sym<<1 | b
					if mb != b {
						break
					}
				}
			}
			for sym < 0x100 {
				sym = sym<<1 | d.bit(&probs[sym])
			}
			d.out = append(d.out, byte(sym))
			switch {
			case d.state < 4:
				d.state = 0
			case d.state < 10:
				d.state -= 3
			default:
				d.state -= 6
			}
			continue
		}
		var length uint32
		if d.bit(&d.isRep[d.state]) == 0 {
			d.rep[3] = d.rep[2]
			d.rep[2] = d.rep[1]
			d.rep[1] = d.rep[0]
			length = d.decodeLen(&d.lenDec, posState)
			if d.state < 7 {
				d.state = 7
			} else {
				d.state = 10
			}
			lenState := length
			if lenState > 3 {
				lenState = 3
			}
			slot := d.bittree(d.posSlot[lenState][:], 6)
			var dist uint32
			if slot < 4 {
				dist = slot
			} else {
				n := uint(slot>>1) - 1
				dist = (2 | (slot & 1)) << n
				if slot < 14 {
					dist += d.revBittree(d.posDec[:], int(dist)-int(slot)-1, n)
				} else {
					dist += d.direct(n-4) << 4
					dist += d.revBittree(d.align[:], -1, 4)
				}
			}
			d.rep[0] = dist
			if dist == 0xFFFFFFFF {
				return nil
			}
		} else {
			if d.bit(&d.isRepG0[d.state]) == 0 {
				if d.bit(&d.isRep0Long[d.state<<4+posState]) == 0 {
					if d.state < 7 {
						d.state = 9
					} else {
						d.state = 11
					}
					d.out = append(d.out, d.getByte(d.rep[0]))
					continue
				}
			} else {
				var dist uint32
				if d.bit(&d.isRepG1[d.state]) == 0 {
					dist = d.rep[1]
				} else {
					if d.bit(&d.isRepG2[d.state]) == 0 {
						dist = d.rep[2]
					} else {
						dist = d.rep[3]
						d.rep[3] = d.rep[2]
					}
					d.rep[2] = d.rep[1]
				}
				d.rep[1] = d.rep[0]
				d.rep[0] = dist
			}
			length = d.decodeLen(&d.repLenDec, posState)
			if d.state < 7 {
				d.state = 8
			} else {
				d.state = 11
			}
		}
		n := int(length) + 2
		src := len(d.out) - int(d.rep[0]) - 1
		if src < d.dictStart || src < 0 {
			return errXZ
		}
		for i := 0; i < n && len(d.out) < target; i++ {
			d.out = append(d.out, d.out[src+i])
		}
	}
	return nil
}

// lzma2Decode decodes an LZMA2 stream; returns output and consumed bytes.
func lzma2Decode(in []byte) ([]byte, int, error) {
	d := &lzmaDecoder{in: in}
	p := 0
	needProps := true
	for {
		if p >= len(in) {
			return d.out, p, errXZ
		}
		ctrl := in[p]
		p++
		if ctrl == 0 {
			return d.out, p, nil
		}
		if ctrl == 1 || ctrl == 2 {
			if p+2 > len(in) {
				return d.out, p, errXZ
			}
			size := (int(in[p])<<8 | int(in[p+1])) + 1
			p += 2
			if p+size > len(in) {
				return d.out, p, errXZ
			}
			if ctrl == 1 {
				d.dictStart = len(d.out)
			}
			d.out = append(d.out, in[p:p+size]...)
			p += size
			continue
		}
		if ctrl < 0x80 {
			return d.out, p, errXZ
		}
		if p+4 > len(in) {
			return d.out, p, errXZ
		}
		unpacked := (int(ctrl&0x1f)<<16 | int(in[p])<<8 | int(in[p+1])) + 1
		packed := (int(in[p+2])<<8 | int(in[p+3])) + 1
		p += 4
		mode := (ctrl >> 5) & 3
		if mode == 3 {
			d.dictStart = len(d.out)
		}
		if mode >= 2 {
			if p >= len(in) {
				return d.out, p, errXZ
			}
			props := int(in[p])
			p++
			d.lc = uint(props % 9)
			props /= 9
			d.lp = uint(props % 5)
			d.pb = uint(props / 5)
			needProps = false
		}
		if needProps {
			return d.out, p, errXZ
		}
		if mode >= 1 {
			d.resetState()
		}
		if p+packed > len(in) {
			return d.out, p, errXZ
		}
		d.in = in[p : p+packed]
		d.ip = 0
		if err := d.rcInit(); err != nil {
			return d.out, p, err
		}
		if err := d.decodeChunk(unpacked); err != nil {
			return d.out, p, err
		}
		p += packed
	}
}
