func readVarint(b []byte, p int) (uint64, int, error) {
	var v uint64
	for i := 0; i < 9; i++ {
		if p >= len(b) {
			return 0, p, errXZ
		}
		c := b[p]
		p++
		v |= uint64(c&0x7f) << (7 * uint(i))
		if c&0x80 == 0 {
			return v, p, nil
		}
	}
	return 0, p, errXZ
