			flags := hdr[1]
			q := 2
			var err error
			if flags&0x40 != 0 {
				_, q, err = readVarint(hdr, q)
				if err != nil {
					return out, err
				}
			}
			if flags&0x80 != 0 {
				_, q, err = readVarint(hdr, q)
				if err != nil {
					return out, err
				}
			}
