			type filter struct {
				id    uint64
				props []byte
			}
			var filters []filter
			for i := 0; i < nf; i++ {
				var id, psz uint64
				id, q, err = readVarint(hdr, q)
				if err != nil {
					return out, err
				}
				psz, q, err = readVarint(hdr, q)
				if err != nil {
					return out, err
				}
				if q+int(psz) > len(hdr) {
