				if d.bit(&d.isRepG1[d.state]) == 0 {
					dist = d.rep[1]
				} else {
					if d.bit(&d.isRepG2[d.state]) == 0 {
						dist = d.rep[2]
					} else {
						dist = d.rep[3]
						d.rep[3] = d.rep[2]
					}
					d.rep[2] = d.rep[1]
				}
				d.rep[1] = d.rep[0]
				d.rep[0] = dist
			}
