		}
		for i := 0; i < n && len(d.out) < target; i++ {
			d.out = append(d.out, d.out[src+i])
		}
	}
	return nil
}

// lzma2Decode decodes an LZMA2 stream; returns output and consumed bytes.
func lzma2Decode(in []byte) ([]byte, int, error) {
	d := &lzmaDecoder{in: in}
	p := 0
	needProps := true
	for {
		if p >= len(in) {
			return d.out, p, errXZ
		}
		ctrl := in[p]
		p++
		if ctrl == 0 {
			return d.out, p, nil
		}
		if ctrl == 1 || ctrl == 2 {
			if p+2 > len(in) {
				return d.out, p, errXZ
			}
			size := (int(in[p])<<8 | int(in[p+1])) + 1
			p += 2
			if p+size > len(in) {
				return d.out, p, errXZ
			}
			if ctrl == 1 {
				d.dictStart = len(d.out)
			}
			d.out = append(d.out, in[p:p+size]...)
			p += size
			continue
		}
		if ctrl < 0x80 {
			return d.out, p, errXZ
		}
		if p+4 > len(in) {
			return d.out, p, errXZ
		}
		unpacked := (int(ctrl&0x1f)<<16 | int(in[p])<<8 | int(in[p+1])) + 1
		packed := (int(in[p+2])<<8 | int(in[p+3])) + 1
		p += 4
		mode := (ctrl >> 5) & 3
		if mode == 3 {
			d.dictStart = len(d.out)
		}
		if mode >= 2 {
			if p >= len(in) {
				return d.out, p, errXZ
			}
			props := int(in[p])
			p++
			d.lc = uint(props % 9)
			props /= 9
			d.lp = uint(props % 5)
			d.pb = uint(props / 5)
			needProps = false
		}
		if needProps {
			return d.out, p, errXZ
		}
		if mode >= 1 {
			d.resetState()
		}
		if p+packed > len(in) {
			return d.out, p, errXZ
		}
		d.in = in[p : p+packed]
		d.ip = 0
		if err := d.rcInit(); err != nil {
			return d.out, p, err
		}
		if err := d.decodeChunk(unpacked); err != nil {
			return d.out, p, err
		}
		p += packed
	}
}
