	}
	modes := b[p]
	p++
	readTable := func(mode byte, def *fseTable, prev *fseTable, maxSym, maxAL int) (*fseTable, error) {
		switch mode {
		case 0:
			return def, nil
		case 1:
			if p >= len(b) {
				return nil, errZstd
			}
			t := rleFSE(int(b[p]))
			p++
			return t, nil
		case 2:
			br := &fwdBits{b: b[p:]}
			counts, al, err := readFSECounts(br, maxSym, maxAL)
			if err != nil {
				return nil, err
			}
			p += (br.pos + 7) / 8
			return buildFSE(counts, al), nil
		case 3:
			if prev == nil {
				return nil, errZstd
			}
			return prev, nil
		}
		return nil, errZstd
	}
	var err error
	if st.ll, err = readTable(modes>>6, llDefTable, st.ll, 35, 9); err != nil {
		return out, err
	}
	if st.of, err = readTable((modes>>4)&3, ofDefTable, st.of, 31, 8); err != nil {
		return out, err
	}
	if st.ml, err = readTable((modes>>2)&3, mlDefTable, st.ml, 52, 9); err != nil {
		return out, err
	}
	rb, err := newRevBits(b[p:])
	if err != nil {
		return out, err
	}
	llS := int(rb.read(st.ll.al))
	ofS := int(rb.read(st.of.al))
	mlS := int(rb.read(st.ml.al))
	litPos := 0
	for i := 0; i < nseq; i++ {
		llE := st.ll.table[llS]
		ofE := st.of.table[ofS]
		mlE := st.ml.table[mlS]
		ofCode := int(ofE.sym)
		if int(mlE.sym) >= len(mlBase) || int(llE.sym) >= len(llBase) || ofCode > 31 {
			return out, errZstd
		}
		ofVal := (uint32(1) << uint(ofCode)) + rb.read(ofCode)
		ml := mlBase[mlE.sym] + rb.read(int(mlBits[mlE.sym]))
		ll := llBase[llE.sym] + rb.read(int(llBits[llE.sym]))
		var offset uint32
		if ofVal > 3 {
			offset = ofVal - 3
			st.rep[2] = st.rep[1]
			st.rep[1] = st.rep[0]
			st.rep[0] = offset
		} else {
			idx := ofVal
			if ll == 0 {
				idx++
			}
			switch idx {
			case 1:
				offset = st.rep[0]
			case 2:
				offset = st.rep[1]
				st.rep[1] = st.rep[0]
				st.rep[0] = offset
			case 3:
				offset = st.rep[2]
				st.rep[2] = st.rep[1]
				st.rep[1] = st.rep[0]
				st.rep[0] = offset
			case 4:
				offset = st.rep[0] - 1
				st.rep[2] = st.rep[1]
				st.rep[1] = st.rep[0]
				st.rep[0] = offset
			}
		}
		if litPos+int(ll) > len(lits) {
			return out, errZstd
		}
		out = append(out, lits[litPos:litPos+int(ll)]...)
		litPos += int(ll)
		start := len(out) - int(offset)
		if offset == 0 || start < frameStart {
			return out, errZstd
		}
		n := int(ml)
		if int(offset) >= n {
			out = append(out, out[start:start+n]...)
		} else {
			for k := 0; k < n; k++ {
				out = append(out, out[start+k])
			}
		}
		if i < nseq-1 {
			llS = int(llE.newState) + int(rb.read(int(llE.nbBits)))
			mlS = int(mlE.newState) + int(rb.read(int(mlE.nbBits)))
			ofS = int(ofE.newState) + int(rb.read(int(ofE.nbBits)))
		}
	}
	out = append(out, lits[litPos:]...)
	return out, nil
}
