	}
}

// alignSegments splits a line into column segments for alignment.
// Each segment except the first begins with the delimiter.
func (root *Root) alignSegments(d *Document, ln int, lc contents) []colRange {
	cols := root.columnRanges(d, ln, lc)
	if len(cols) <= 1 {
		return nil
	}
	var segs []colRange
	start := 0
	for i := 0; i < len(cols)-1; i++ {
		end := cols[i].end
		segs = append(segs, colRange{start, end})
		start = end
	}
	segs = append(segs, colRange{start, len(lc)})
	return segs
}

// updateAlignWidths computes column widths from the lines around the screen.
func (root *Root) updateAlignWidths(d *Document) {
	root.prepareAlign(d)
	ai := d.alignInfo
	var widths []int
	add := func(ln int) {
		lc := root.rawContentsOf(d, ln)
		segs := root.alignSegments(d, ln, lc)
		for i, sg := range segs {
			if i == len(segs)-1 {
				break
			}
			w := sg.end - sg.start
			if i >= len(widths) {
				widths = append(widths, w)
			} else if w > widths[i] {
				widths[i] = w
			}
		}
	}
	hs, he := d.headerRange()
	for ln := hs; ln < he; ln++ {
		add(ln)
	}
	total := d.BufEndNum()
	end := d.topLN + root.height
	for ln := d.topLN; ln < end && ln < total; ln++ {
		add(ln)
	}
	key := ""
	for _, w := range widths {
		key += strconvItoa(w) + ","
	}
	if key != ai.key {
		ai.key = key
		ai.widths = widths
		d.clearCache()
	}
