	}
	return parseLine(line, d.General.TabWidth, d.conv, d.plain)
}

func (root *Root) alignContents(d *Document, n int, lc contents) contents {
	ai := d.alignInfo
	if ai == nil {
		return lc
	}
	segs := root.alignSegments(d, n, lc)
	if len(segs) == 0 {
		return lc
	}
	res := make(contents, 0, len(lc)+len(segs)*2)
	for i, sg := range segs {
		part := lc[sg.start:sg.end]
		if i == len(segs)-1 {
			if ai.shrink[i] {
				res = append(res, shrinkPart(part, i > 0)...)
			} else {
				res = append(res, part...)
			}
			break
		}
		w := sg.end - sg.start
		max := w
		if i < len(ai.widths) {
			max = ai.widths[i]
		}
		if ai.shrink[i] {
			res = append(res, shrinkPart(part, i > 0)...)
			res = append(res, DefaultContent)
			continue
		}
		pad := max + 1 - w
		if ai.right[i] {
			if i > 0 && len(part) > 0 {
				res = append(res, part[0])
				part = part[1:]
			}
			for k := 0; k < pad; k++ {
				res = append(res, DefaultContent)
			}
			res = append(res, part...)
			continue
		}
		res = append(res, part...)
		for k := 0; k < pad; k++ {
			res = append(res, DefaultContent)
		}
	}
