	root.prepareAlign(d)
	c := d.columnCursor
	d.alignInfo.shrink[c] = !d.alignInfo.shrink[c]
	d.alignInfo.key = ""
	d.clearCache()
	root.setMessagef("Set shrink column %d %v", c, d.alignInfo.shrink[c])
