	n := d.BufEndNum()
	limit := 1000
	if n > limit {
		n = limit
	}
	var lines []contents
	for i := 0; i < n; i++ {
		lines = append(lines, root.rawContentsOf(d, i))
	}
	d.columnWidths = []int{}
	if len(lines) == 0 {
		return
	}
	hi := d.General.Header + d.General.SkipLines
	if hi >= len(lines) || hi < 0 {
		hi = 0
	}
	if d.General.Header > 0 {
		hi = d.General.SkipLines + d.General.Header - 1
		if hi >= len(lines) {
			hi = 0
		}
	}
	header := lines[hi]
	isBlank := func(lc contents, i int) bool {
		return i >= len(lc) || lc[i].mainc == ' '
	}
	// find gaps in the header line
	var seps []int
	i := 0
	for i < len(header) && header[i].mainc == ' ' {
		i++
	}
	for i < len(header) {
		// skip word
		for i < len(header) && header[i].mainc != ' ' {
			i++
		}
		gs := i
		for i < len(header) && header[i].mainc == ' ' {
			i++
		}
		ge := i
		if ge >= len(header) || gs == ge {
			break
		}
		sep := -1
		for p := ge - 1; p >= gs; p-- {
			all := true
			for li, lc := range lines {
				if li < d.General.SkipLines {
					continue
				}
				if !isBlank(lc, p) {
					all = false
					break
				}
			}
			if all {
				sep = p
				break
			}
		}
		if sep < 0 {
			continue
		}
		seps = append(seps, sep)
	}
	d.columnWidths = seps
}

